__NUXT_JSONP__("/th/testimonials", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{details:{slug:i,pageTitle:"คำรับรองจากนักเรียน | Mentor Language Institute",pageDescription:"Comments about MLI from students.",title:"คำรับรองจากนักเรียน",selectBy:{title:"เลือกโดย:",selections:[{title:"Nationality",key:"nationality",lists:[{title:"All Nationalities",value:j},{image:"\u002Fflags\u002Fsa.png",title:k,link:"ar"},{image:"\u002Fflags\u002Fkr.png",title:g,link:"kr"},{image:"\u002Fflags\u002Fru.png",title:h,link:"ru"},{image:"\u002Fflags\u002Ffr.png",title:n,link:"fr"},{image:"\u002Fflags\u002Fes.png",title:l,link:"sp"},{image:"\u002Fflags\u002Fth.png",title:"Thai",link:i},{image:"\u002Fflags\u002Fjp.png",title:c,link:"jp"},{image:"\u002Fflags\u002Fbr.png",title:f,link:"por"},{image:"\u002Fflags\u002Fcn.png",title:e,link:"ch"},{image:"\u002Fflags\u002Fit.png",title:o,link:"it"},{image:"\u002Fflags\u002Ftr.png",title:m,link:"tr"},{image:"\u002Fflags\u002Fde.png",title:"German",link:"de"},{image:"\u002Fflags\u002Fother.png",title:d,link:j}]},{title:p,key:"campus",lists:[{title:p,value:j},{title:"Westwood",image:"\u002Fcampus\u002Fwestwood.png"},{title:"Hollywood",image:"\u002Fcampus\u002Fhollywood.png"}]}]},comments:{title:" Comments about MLI from students."},readmoreBtn:"อ่านต่อ",dir:"\u002Ftestimonials",path:"\u002Ftestimonials\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:31.224Z",updatedAt:"2025-05-26T12:06:27.937Z"},lang:i,allTestimonials:[{id:90,image:"1761607523-ee42a2a8-83ba-4873-9cbf-df2be365d5cc.JPG",campus_name:a,nationality_name:m,title:"การเดินทางของฉันที่ MLI",text:"สวัสดีค่ะ ฉันชื่อ Merve มาจากตุรกี ฉันได้เรียนคอร์สภาษาอังกฤษเป็นเวลา 6 เดือนที่ MLI และพูดได้เลยว่านี่เป็นหนึ่งในประสบการณ์ที่ดีที่สุดในชีวิตของฉัน ฉันได้พบเพื่อนมากมายจากหลากหลายวัฒนธรรม และมีโอกาสเรียนกับครูมืออาชีพ ทุกคลาสสนุกและน่าจดจำมาก\n\nเราเลือกเมืองลอสแอนเจลิสเพราะเป็นสถานที่ที่เหมาะสำหรับการพบปะผู้คนใหม่ ๆ และแลกเปลี่ยนวัฒนธรรม\n\nตอนที่เริ่มเรียนที่ MLI ฉันพูดภาษาอังกฤษไม่เก่งและไม่มีความมั่นใจ ทุกครั้งที่พยายามพูดฉันรู้สึกประหม่า แต่หลังจากไม่กี่เดือน ทุกอย่างก็เปลี่ยนไป ฉันเริ่มพูดมากขึ้น มีความมั่นใจมากขึ้น และรู้ว่าฉันสามารถทำสิ่งต่าง ๆ ได้ด้วยตัวเอง ตอนนี้ฉันพูดได้ดีขึ้นมาก ขอบคุณเพื่อนร่วมชั้นที่น่ารักของฉันทุกคน\n\nทุกช่วงเวลาที่ MLI มีค่ามาก แต่สิ่งที่ฉันจำได้ดีที่สุดคือวันที่เราไปปิคนิคบาร์บีคิวที่ Pan Pacific Park มันสนุกมาก! เราทานอาหาร เล่นวอลเลย์บอล และพูดคุยกันอย่างมีความสุข\n\nสำหรับอนาคต ฉันอยากทำงานเป็นวิศวกรในสหรัฐอเมริกา ใช้ภาษาอังกฤษในการทำงาน และพัฒนาตัวเองในทุก ๆ วัน"},{id:89,image:"1750786714-Gahyun Kim.JPG",campus_name:b,nationality_name:g,title:"ความทรงจำที่ดีที่สุดของฉันในลอสแองเจลิส",text:"สวัสดีค่ะ! ฉันชื่อลิลลี่  และฉันมาจากเกาหลีใต้ ฉันเรียนที่ MLI ตั้งแต่เดือนมกราคมถึงมีนาคม ฉันฝันมาตลอดว่าจะได้ใช้ชีวิตที่ลอสแองเจลิสและฮอลลีวูด ดังนั้นฉันจึงเลือก MLI โดยเฉพาะเพราะตั้งอยู่บนถนนหลักของฮอลลีวูด! เพียงแค่ก้าวออกจากโรงเรียนและอยู่ใจกลางฮอลลีวูด ก็เป็นประสบการณ์ที่สนุกและตื่นเต้นมาก\n\nทำไมถึงเลือกลอสแองเจลิส?\nฉันเลือก LA เพราะคิดว่าเป็นเมืองที่เต็มไปด้วยสิ่งสนุก ๆ ให้ทำ — และฉันคิดถูกมาก! ใกล้ ๆ มีทั้งชายหาดและภูเขา และฉันชอบสำรวจสถานที่อย่างซานตาโมนิก้า, หอดูดาวกริฟฟิธ และศูนย์ Getty ทุก ๆ สุดสัปดาห์เหมือนเป็นการผจญภัยใหม่\n\nพัฒนาภาษาอังกฤษและประสบการณ์ในชั้นเรียนที่ MLI\nที่ MLI ฉันอยู่ในคลาสกับนักเรียนจากทั่วโลก ซึ่งช่วยให้ฉันพัฒนาภาษาอังกฤษอย่างเป็นธรรมชาติ เราฝึกพูดทุกวัน และฉันมีความมั่นใจมากขึ้นในการใช้ภาษาอังกฤษในสถานการณ์ต่าง ๆ ด้วยความช่วยเหลือจากครูและเพื่อนร่วมชั้น ฉันเรียนวิชากรามมาร์ การสื่อสาร และภาษาอังกฤษธุรกิจ\nนอกจากนี้ เจ้าหน้าที่ของ MLI ก็ใจดีและให้การสนับสนุนเสมอ พวกเขายินดีช่วยเหลือทุกเรื่อง ทั้งในและนอกห้องเรียน ซึ่งทำให้ฉันรู้สึกสะดวกสบายและได้รับการต้อนรับตลอดช่วงเวลาอยู่ที่นั่น\n\nช่วงเวลาที่ประทับใจ\nสิ่งที่ฉันชอบที่สุดใน MLI คือกิจกรรมที่หลากหลาย ฉันเข้าร่วมทริปลาสเวกัส ปาร์ตี้บาร์บีคิว และวันในดิสนีย์แลนด์ และทั้งหมดนั้นลืมไม่ลง! สิ่งที่ทำให้พิเศษจริง ๆ คือ ฉันได้ใช้เวลากับเพื่อนนักเรียนเกาหลีและเพื่อนนานาชาติ กิจกรรมเหล่านี้ช่วยให้เราได้สร้างความสัมพันธ์ และหลายคนจากพวกเราออกไปเที่ยวด้วยกันนอกโรงเรียนบ่อยครั้ง\n\nแผนในอนาคต\nตอนนี้ ฉันกำลังฝึกงานที่องค์กรไม่แสวงหากำไรสำหรับเด็กใน LA แผนของฉันคือสร้างประสบการณ์ที่นี่ต่อไปและหวังว่าจะได้ทำงานในสาขานี้ ฉันตื่นเต้นที่จะได้เรียนรู้และเติบโตในเมืองนี้ และฉันมั่นใจว่าความทรงจำที่ฉันได้สร้างที่ MLI คือความทรงจำที่ดีที่สุดใน LA ของฉัน!"},{id:88,image:"1744833045-Testimonials _Yoonbin.jpg",campus_name:a,nationality_name:e,title:"ประสบการณ์ครั้งแรกของฉันในโรงเรียนสอนภาษาและการฝึกงานในสหรัฐอเมริกา",text:"สวัสดี! ฉันชื่อ ยุนบิน แบ มาจากเกาหลีใต้ ฉันเพิ่งเรียนจบหลักสูตรภาษาที่ MLI และขณะนี้กำลังฝึกงานอยู่ ตลอดเวลาที่ MLI ฉันมีโอกาสได้พบปะผู้คนจากวัฒนธรรมที่หลากหลาย พร้อมกับพัฒนาทักษะภาษาอังกฤษของฉัน ในชั้นเรียนระดับสูง ฉันได้พัฒนาความแม่นยำในการใช้ภาษาอังกฤษ พูดได้อย่างเป็นธรรมชาติมากขึ้น และเสริมสร้างทักษะการคิดเชิงวิเคราะห์ ผ่านการสนทนาระดับสูง การเขียนเรียงความเชิงวิชาการ และการอ่านเชิงวิเคราะห์\n\n- ทำไมต้องลอสแอนเจลิส?\n\nฉันเลือกมาที่ลอสแอนเจลิสเพราะฉันมีความผูกพันพิเศษกับเมืองนี้ เมื่อสิบปีก่อน ฉันเคยเรียนชั้นประถมและมัธยมต้นที่นี่ ซึ่งเป็นช่วงเวลาที่ฉันวางรากฐานด้านภาษาอังกฤษและสร้างความทรงจำที่ยอดเยี่ยมกับผู้คนจากหลากหลายวัฒนธรรม ประสบการณ์อันมีค่านี้ทำให้ฉันอยากกลับมาสหรัฐอเมริกาอีกครั้ง นอกจากนี้ สภาพอากาศที่ดีและผู้คนที่เป็นมิตรของลอสแอนเจลิสยังทำให้ที่นี่เป็นสถานที่ที่เหมาะแก่การพัฒนาภาษาอังกฤษของฉันต่อไป\n\n- การพัฒนาภาษาอังกฤษ\n\nการเรียนที่ MLI ช่วยพัฒนาทักษะภาษาอังกฤษของฉันอย่างมาก แม้ว่าฉันจะมีพื้นฐานอยู่แล้ว แต่การไม่ได้ใช้ภาษาอังกฤษมานานทำให้ฉันพูดไม่คล่อง อย่างไรก็ตาม ด้วยการสนับสนุนจากอาจารย์ ฉันจึงมั่นใจมากขึ้นในการสื่อสารความคิดของฉันอย่างชัดเจนและถูกต้อง\n\n- ช่วงเวลาที่น่าจดจำที่สุด\n\nกิจกรรมที่ฉันประทับใจที่สุดที่ MLI คือการเดินทางไปลาสเวกัส เป็นเวลา 3 วัน 2 คืน ที่ฉันและเพื่อนได้สำรวจโรงแรมที่มีสไตล์เหมือนประเทศต่างๆ ถ่ายรูปมากมายภายใต้แสงไฟนีออนที่สวยงาม และชมโชว์น้ำพุเบลลาจิโอที่มีชื่อเสียง เราเดินทางด้วยรถบัสนาน 10 ชั่วโมงเพื่อไปชมความงดงามของแกรนด์แคนยอน การได้แบ่งปันช่วงเวลาที่น่าทึ่งเหล่านี้กับเพื่อนๆ ทำให้ประสบการณ์นี้พิเศษยิ่งขึ้น และฉันจะจดจำมันไปตลอดชีวิต\n\n- แผนในอนาคต\n\nเป้าหมายหลักของฉันในตอนนี้คือการฝึกงานให้สำเร็จ หลังจากนั้น ฉันต้องการทำงานในบริษัทข้ามชาติ โดยใช้ทักษะภาษาอังกฤษที่พัฒนาขึ้นและความรู้ด้านการตลาดที่ฉันได้รับจากการฝึกงาน เวลาที่ MLI ทำให้ฉันมีความมั่นใจและมุมมองที่กว้างขึ้น เตรียมพร้อมสำหรับอาชีพในสภาพแวดล้อมการทำงานระดับโลก\n\nประสบการณ์ของฉันที่ MLI ไม่ใช่แค่การเรียนภาษาอังกฤษเท่านั้น แต่มันเป็นการเดินทางแห่งการเติบโตและการค้นพบตัวเอง ผ่านการมีปฏิสัมพันธ์ที่มีความหมายกับเพื่อนๆ จากทั่วโลก ฉันได้ขยายมุมมองของฉันและก้าวแรกสู่ความฝันของตัวเอง ขอบคุณ MLI!"},{id:87,image:"1743099948-IMG_9244.jpg",campus_name:a,nationality_name:g,title:"ประสบการณ์ที่ดีที่สุดใน MLI!",text:"สวัสดีค่ะ ฉันชื่อซอฮยอน ชิน มาจากประเทศเกาหลี ฉันได้เรียนที่ MLI ประมาณสองเดือน และประสบการณ์ที่ฉันได้รับที่นี่มีค่ามากและเต็มไปด้วยความสุขจริงๆ ฉันอยากจะอยู่ต่ออีกนานกว่านี้ แต่โชคไม่ดีที่ฉันต้องจบการศึกษาเร็วกว่ากำหนดเนื่องจากตารางการฝึกงานที่กำลังจะมาถึง ซึ่งทำให้ฉันรู้สึกเสียใจมาก ตอนนี้ขอให้ฉันเล่าให้ฟังว่าทำไมฉันถึงเรียกมันว่าเป็นประสบการณ์ที่ดีที่สุดใน MLI!\n\n◉ทำไมต้องลอสแอนเจลิส?\nการเลือกเรียนภาษาอังกฤษที่ลอสแอนเจลิสเป็นหนึ่งในสิ่งที่ดีที่สุดที่ฉันเคยตัดสินใจในชีวิต ลอสแอนเจลิสเป็นเมืองที่เต็มไปด้วยความหลากหลายทางวัฒนธรรม และฉันรู้ว่าการเรียนที่นี่จะเปิดโอกาสให้ฉันได้พบปะผู้คนจากทั่วโลก บรรยากาศที่มีชีวิตชีวาของเมืองนี้ ชุมชนที่หลากหลาย และโอกาสไม่รู้จบในการฝึกพูดภาษาอังกฤษในสถานการณ์จริงทำให้ที่นี่เป็นสถานที่ที่สมบูรณ์แบบในการพัฒนาทักษะทางภาษา ตั้งแต่การเดินชมถนนฮอลลีวูดวอล์กออฟเฟมไปจนถึงการเพลิดเพลินกับวันแดดจ้าที่ชายหาดซานตาโมนิกา ทุกๆ วันในลอสแอนเจลิสเป็นการผจญภัยที่เติมเต็มประสบการณ์การเรียนรู้ของฉัน\n\n◉การพัฒนาทักษะภาษาอังกฤษของฉัน\nในช่วงเวลาที่ฉันเรียนที่ MLI ทักษะด้านการอ่าน การฟัง และไวยากรณ์ของฉันดีขึ้นอย่างมาก โดยเฉพาะอย่างยิ่งคลาสภาษาอังกฤษธุรกิจที่ช่วยให้ฉันมีความมั่นใจในการสื่อสารในสภาพแวดล้อมทางวิชาชีพ ครูทุกคนใจดีและให้การสนับสนุนอย่างเต็มที่ และบทเรียนที่มีการโต้ตอบกันช่วยให้ฉันเข้าใจหลักไวยากรณ์ที่ซับซ้อนและพัฒนาการฟังได้ดีขึ้น ฉันสังเกตว่าตัวเองเริ่มพูดได้อย่างคล่องแคล่วและเป็นธรรมชาติมากขึ้น ไม่ว่าจะเป็นการพูดคุยกับเพื่อนร่วมชั้นหรือการใช้ชีวิตประจำวันในลอสแอนเจลิส\n\n◉ช่วงเวลาที่น่าจดจำ\nหนึ่งในช่วงเวลาที่น่าจดจำที่สุดใน MLI คือการเดินทางสามวันไปยังลาสเวกัส การเดินทางกับเพื่อนร่วมชั้น การสำรวจแสงสีของเมือง และการสัมผัสบรรยากาศที่มีชีวิตชีวาทำให้ฉันมีความทรงจำที่ไม่มีวันลืม งานปาร์ตี้บาร์บีคิวและการเดินทางไปดิสนีย์แลนด์ก็เป็นช่วงเวลาที่พิเศษเช่นกัน — ฉันได้สร้างมิตรภาพกับเพื่อนจากหลากหลายประเทศในขณะที่เพลิดเพลินกับอาหารอร่อยและเครื่องเล่นที่สนุกสนาน การได้ร่วมฉลองเทศกาลทางวัฒนธรรม เช่น วันตรุษจีนและวันวาเลนไทน์ ทำให้ฉันรู้สึกเชื่อมโยงกับชุมชน MLI และสร้างความรู้สึกเป็นส่วนหนึ่งที่ฉันจะจดจำไปตลอดชีวิต\n\n◉แผนในอนาคต\nประสบการณ์ที่ MLI ทำให้ฉันมีความมั่นใจและทักษะที่จำเป็นในการบรรลุเป้าหมายในอนาคต ต้องขอบคุณคลาสภาษาอังกฤษธุรกิจและทักษะการสื่อสารที่ดีขึ้น ฉันรู้สึกว่าพร้อมที่จะเริ่มต้นการฝึกงานและทำงานในสภาพแวดล้อมระดับนานาชาติ ฉันรู้สึกตื่นเต้นที่จะได้นำทุกสิ่งที่ฉันได้เรียนรู้ที่ MLI ไปใช้ในเส้นทางอาชีพในอนาคต และฉันมั่นใจว่ามิตรภาพและประสบการณ์ที่ฉันได้รับที่นี่จะอยู่กับฉันไปตลอดชีวิต"},{id:86,image:"1739488748-Testimonials_Yuka.jpg",campus_name:a,nationality_name:c,title:"ความทรงจำอันล้ำค่าของฉันตลอด 10 เดือนที่ผ่านมา",text:"ฉันชื่อยูกะ มาจากประเทศญี่ปุ่น ฉันเรียนที่ MLI มาเป็นเวลา 8 เดือนแล้ว เพราะฉันต้องการพูดภาษาอังกฤษให้คล่องและมีเพื่อนมากมาย ผ่านโรงเรียนแห่งนี้ ฉันได้พบกับคุณครูที่ยอดเยี่ยมและเพื่อนที่วิเศษมาก การใช้ชีวิตที่นี่ทำให้ฉันมีความทรงจำและประสบการณ์ที่ลืมไม่ลง\n\nทำไมต้องเป็นลอสแอนเจลิส?\nสามีของฉันอาศัยอยู่ที่ลอสแอนเจลิสมาเป็นเวลา 7 ปีแล้ว เราแต่งงานกันเมื่อปีครึ่งที่แล้ว และฉันย้ายมาที่นี่เมื่อ 8 เดือนก่อนเพื่อมาอยู่กับเขา ตอนที่ฉันยังเป็นนักเรียนมัธยมต้น ฉันเคยมาเที่ยวลอสแอนเจลิสไม่กี่วัน ซึ่งเป็นหนึ่งในความทรงจำที่มีค่าของฉัน แต่ฉันไม่เคยคาดคิดมาก่อนว่าฉันจะได้มาใช้ชีวิตที่นี่\n\nพัฒนาการด้านภาษาอังกฤษของฉัน\nเมื่อปีที่แล้ว ฉันต้องพึ่งพาสามีของฉันในการแปลภาษาทุกครั้งที่สั่งอาหารในร้านอาหารหรือพูดคุยกับเพื่อนชาวอเมริกัน แต่เมื่อเร็ว ๆ นี้ ฉันเริ่มสามารถสั่งอาหารหรือพูดสิ่งต่าง ๆ ด้วยตัวเองได้แล้ว นอกจากทักษะการพูดของฉันจะดีขึ้นแล้ว ทักษะการเขียนของฉันก็พัฒนาขึ้นเช่นกัน เพราะฉันมีการบ้านให้เขียนไดอารี่เป็นภาษาอังกฤษ\n\nช่วงเวลาที่น่าจดจำในลอสแอนเจลิส\nวันที่ 4 กรกฎาคมของทุกปีเป็นวันประกาศอิสรภาพของสหรัฐอเมริกา ซึ่งเป็นวันหยุดที่สำคัญพอ ๆ กับวันคริสต์มาสและวันฮาโลวีน แม้ว่าหลายรัฐในสหรัฐอเมริกาจะมีข้อจำกัดเกี่ยวกับการจุดพลุ แต่ในวันนี้พวกเขาได้รับอนุญาตให้จุดได้เป็นพิเศษ\nในวันนั้น ฉันไปบ้านเพื่อนของฉัน อพาร์ตเมนต์ของพวกเขาอยู่ในตึกสูง 20 ชั้น และเราสามารถชมดอกไม้ไฟจากดาดฟ้าได้ ทิวทัศน์เปิดกว้าง และไม่ว่าเราจะมองไปทางไหนก็เห็นดอกไม้ไฟที่สวยงามเต็มไปหมด! ดอกไม้ไฟเป็นหนึ่งในเอกลักษณ์ของฤดูร้อนในญี่ปุ่น ฉันเคยเห็นดอกไม้ไฟมาหลายครั้งแล้ว แต่ฉันไม่เคยมีประสบการณ์อะไรที่น่าตื่นเต้นแบบนี้มาก่อน\n\nแผนในอนาคตของฉัน\nจริง ๆ แล้ว ฉันตั้งใจจะอยู่ที่นี่นานกว่านี้ แต่ด้วยเหตุผลหลายประการ ฉันต้องกลับญี่ปุ่นพร้อมกับสามีในเดือนหน้า ดังนั้นฉันวางแผนที่จะจัดตารางเวลาเพื่อให้สามารถเรียนบทสนทนาภาษาอังกฤษอย่างน้อยสัปดาห์ละหนึ่งหรือสองครั้ง และในอนาคต ฉันอยากจะมีโอกาสใช้ชีวิตในต่างประเทศกับครอบครัวอีกครั้ง ฉันคิดว่ามันคงจะไม่ใช่เรื่องไกลเกินเอื้อม"},{id:85,image:"1739488466-IMG_0528.jpg",campus_name:a,nationality_name:d,title:"MLI คือตัวแทนที่ดีที่สุดของลอสแองเจลิส",text:"ชื่อของฉันคือกลอเรีย ฉันมาจากโคลอมเบีย ตั้งแต่ครั้งแรกที่ติดต่อ MLI มันเป็นประสบการณ์ที่ยอดเยี่ยมมากจากความเอื้ออาทรของพนักงานที่แผนกต้อนรับ ฉันรู้ทันทีว่านี่คือโรงเรียนที่เหมาะสมที่สุดสำหรับฉันในการเรียนรู้ภาษาอังกฤษ\n\nก่อนที่ฉันจะย้ายมาเรียนที่ลอสแองเจลิส ฉันอาศัยอยู่ที่บอสตัน รัฐแมสซาชูเซตส์ และตัดสินใจย้ายมาที่นี่ด้วยเหตุผลสำคัญ 3 ประการ:\n\nลอสแองเจลิสมีสภาพอากาศที่ดีที่สุดตลอดทั้ง 4 ฤดู มันเหมือนกับเมืองเมเดลลิน บ้านเกิดของฉัน\nลอสแองเจลิสเป็นศูนย์กลางของความบันเทิง และโรงเรียนมีโปรแกรมกิจกรรมที่ครบครันในการพาไปเยี่ยมชมสถานที่ท่องเที่ยวทุกสัปดาห์\nฉันสามารถพบปะกับคนจากประเทศอื่นๆ การได้เรียนรู้เกี่ยวกับวัฒนธรรมของพวกเขาทำให้ฉันตื่นเต้น และฉันวางแผนที่จะไปเยือนในอนาคต\nความท้าทายของฉันคือการพูดภาษาอังกฤษให้คล่อง และฉันพบว่าทุกๆ อาจารย์ที่ MLI มีความหลงใหล รัก และมีความอดทนในการสอน ฉันมั่นใจว่าฉันจะทำได้\n\nช่วงเวลาที่ดีที่สุดของฉันที่ MLI คือกิจกรรมฤดูร้อนที่หาดเวนิส ฉันได้แชร์เวลาที่น่าทึ่งกับอาจารย์และนักเรียนจากทั้งสองแคมปัสที่ฮอลลีวูดและเวสต์วูด การจัดระเบียบที่ไร้ที่ติ อาหารอร่อย และการเล่นเกมสนุกๆ ทำให้วันนั้นกลายเป็นความทรงจำที่ไม่อาจลืม\n\nเมื่อฉันเรียนจบจาก MLI ฉันต้องการที่จะศึกษาต่อในสาขาการจัดการโรงแรมที่นี่ในลอสแองเจลิส และสามารถทำงานในภาคโรงแรมกับเครือโรงแรมระดับโลกต่อไป"},{id:84,image:"1739488177-IMG_3762.jpg",campus_name:a,nationality_name:d,title:"การเรียนรู้ การเชื่อมโยง และการสำรวจ: ชีวิตของฉันที่ MLI ในลอสแอนเจลิส",text:"สวัสดีค่ะ ฉันชื่อเลสลี่ มาจากเม็กซิโก ฉันอาศัยอยู่ในลอสแอนเจลิสมาเป็นเวลา 2 ปีแล้ว และกำลังเรียนที่ MLI เพื่อพัฒนาความรู้ภาษาอังกฤษและเรียนรู้เกี่ยวกับวัฒนธรรมที่หลากหลายในเมืองนี้\n\nฉันคิดว่า MLI เป็นสถานที่ที่ยอดเยี่ยมในการเรียนภาษาอังกฤษในลอสแอนเจลิส บรรยากาศที่นี่เป็นกันเองและเต็มไปด้วยพลังบวก ทำให้ฉันรู้สึกเหมือนอยู่บ้าน หนึ่งในสิ่งที่ฉันประทับใจมากที่สุดคือการสนับสนุนจากคุณครูและเจ้าหน้าที่ คุณครูที่ฉันชื่นชอบมากที่สุดคือครูทอม ท่านมีความอดทนและให้กำลังใจฉันตลอดเส้นทางการเรียน ท่านอธิบายเนื้อหาให้ฉันหลายครั้งจนกว่าฉันจะเข้าใจอย่างถ่องแท้ ทำให้วิธีการเรียนรู้ของฉันเปลี่ยนไปอย่างมาก\n\nก่อนที่จะมาเรียนที่ MLI ฉันไม่เคยคิดเลยว่าฉันจะได้พบกับเพื่อนจากหลากหลายประเทศ และได้เรียนรู้เกี่ยวกับวัฒนธรรมของเอเชียและยุโรป นอกจากนี้ ฉันยังได้พบเพื่อนที่ยอดเยี่ยมทั้งจากเจ้าหน้าที่และเพื่อนร่วมชั้นเรียน ซึ่งทำให้ช่วงเวลาของฉันที่นี่พิเศษยิ่งขึ้น ลอสแอนเจลิสยังช่วยให้ฉันเข้าใจวัฒนธรรมของอเมริกากลางและอเมริกาใต้มากขึ้น ซึ่งทำให้ฉันมีมุมมองที่กว้างขึ้น\n\nฉันเลือกที่จะใช้ชีวิตในลอสแอนเจลิสด้วยหลายเหตุผล หนึ่งคือสภาพอากาศที่อบอุ่น อีกเหตุผลหนึ่งคือความใกล้ชิดกับเม็กซิโก และอีกเหตุผลคือฉันสามารถเพลิดเพลินกับอาหารจากหลากหลายวัฒนธรรมได้ เนื่องจากฉันมาจากชนบท การใช้ชีวิตในเมืองใหญ่จึงเป็นการผจญภัยที่น่าตื่นเต้นมาก ฉันชอบแสงไฟของเมืองในตอนกลางคืน ความงดงามของภูเขา และที่นี่เป็นที่แรกที่ฉันได้สัมผัสหิมะ ซึ่งเป็นประสบการณ์ที่น่าทึ่งมาก!\n\nเมื่อฉันเริ่มเรียนที่ MLI ฉันอยู่ในระดับเริ่มต้น แต่ตอนนี้หนึ่งปีผ่านไป ฉันก้าวขึ้นมาสู่ระดับสูงแล้ว มันไม่ใช่เรื่องง่ายเลย แต่ทุกความท้าทายนั้นคุ้มค่ามาก เป้าหมายต่อไปของฉันคือการเรียนหลักสูตรเตรียมสอบ TOEFL"},{id:79,image:"1681173263-unnamed (1).jpg",campus_name:a,nationality_name:c,title:"การสำรวจลอสแอนเจลิสและเพิ่มภาษาอังกฤษที่ MLI",text:"ในสัปดาห์นี้เรามีความตื่นเต้นที่จะมี Myu นักเรียนที่กระตือรือร้นมากจากประเทศญี่ปุ่นที่เข้าร่วมโปรแกรมเรียนภาษาอังกฤษสำหรับผู้เริ่มต้นของเราเร็ว ๆ นี้ Myu ชื่นชอบการเรียนรู้และฝึกภาษาอังกฤษกับเพื่อนร่วมชั้นจากทุกส่วนของโลก\nนอกจากความหลงไหลในการเรียนภาษา Myu ยังมีความสนใจอย่างมากในการสำรวจสถานที่และวัฒนธรรมใหม่ ๆ\n\n\"ฉันเข้าเรียนที่โรงเรียนนี้เป็นเวลาหนึ่งสัปดาห์ ก่อนที่จะได้เข้าเรียน เราจะถูกทดสอบก่อนและจะถูกจัดให้เรียนในระดับที่เหมาะสมที่สุด มีนักเรียนประมาณ 10 คนในเวลานั้น ๆ และระยะห่างระหว่างครูและนักเรียนใกล้เคียงกันมากเลยทำให้ฉันสามารถเพลิดเพลินไปกับการเรียนได้ ภายใต้คำขวัญ \"สอนเฉพาะภาษาอังกฤษ\" คุณสามารถเรียนรู้การออกเสียง ไวยากรณ์ การสนทนาและอื่น ๆ ร่วมกับเพื่อนร่วมชั้นจากหลายประเทศได้ หลังเรียนเสร็จฉันไปที่หาดเวนิสกับเพื่อนของฉัน มันเป็นเวลาที่ผ่อนคล\""},{id:78,image:"1678978291-1678926029-image1.jpeg",campus_name:a,nationality_name:c,title:"ประสบการณ์ที่จะไม่ลืมได้ของฉันที่สถาบันภาษาเมนเทอร์ในลอสแอนเจลิส",text:"ในสัปดาห์นี้เรามี Kaima นักเรียนจากประเทศญี่ปุ่นที่ลงทะเบียนเรียนในโปรแกรมขั้นพื้นฐานของเรา Kaima ชอบสนทนากับนักเรียนต่างชาติและมีโอกาสเดินทางไปยังสถานที่หลายแห่ง รวมถึงลาสเวกัสและ LACMA ที่เขามีความสุขกับมาก\n\n\"ชีวิตที่นี่เยี่ยมมาก\n\nเมนเทอร์เป็นโรงเรียนที่ยอดเยี่ยม หากคุณต้องการเรียนภาษาอังกฤษ ฉันขอแนะนำให้เรียนรู้จริง ๆ ที่นี่ MLI มีหลากหลายชั้นเรียนภาษาอังกฤษ เช่น ESL, TOEFL, Conversation ฯลฯ ดังนั้นคุณสามารถเลือกชั้นเรียนตามระดับของคุณได้ นอกจากนี้ คุณครูและนักเรียนทุกคนเป็นมิตร ทำให้เรียนรู้ได้อย่างมีความสุข\nการพูดภาษาอังกฤษเป็นเรื่องจำเป็นตลอดเวลาเมื่อต้องสื่อสารกับผู้อื่น ซึ่งนำไปสู่โอกาสในการฝึกฝนทักษะในการใช้ภาษาอย่างมากมาย ฉันกำลังศึกษาภาษาอังกฤษเพราะฉันต้องการพูดได้เป็นธรรมชาติ และการอยู่ที่นี่จะช่วยพัฒนาทักษะของคุณอย่างแน่นอน ในเพีย\""},{id:72,image:"1678977317-1628066080-aayush.jpg",campus_name:b,nationality_name:d,title:"Aayush - India",text:"Aayush มาจากเมืองวาโดดาร่า รัฐคุชราต ประเทศอินเดีย เขาอยากเป็นนักแอนิเมชั่นและศิลปิน เขาจึงเดินทางมาอเมริกาเพื่อศึกษาเกี่ยวกับแอนิเมชั่น ในสหรัฐอเมริกา Aayush ตัดสินใจจะเป็นผู้อำนวยการสร้างภาพยนตร์เพื่อผลิตภาพยนตร์แอนิเมชั่นของตัวเอง 4 เดือนที่ผ่านมาเขาได้ศึกษาหลักสูตร Business\u002FTOEIC ที่ MLI Hollywood เพื่อพัฒนาทักษะภาษาอังกฤษของเขา วันนี้ฉันได้คุยกับ Aayush เกี่ยวกับวิธีการประหยัดเงินใน Los Angeles นี่คือสิ่งที่เขาพูด....\n                    บริการขนส่งสาธารณะใน LA ค่อนข้างดีมาก คุณสามารถประหยัดค่าใช้จ่ายโดยการรับบัตรโดยสารรถไฟใต้ดินรายสัปดาห์หรือรายเดือนที่เรียกว่า tap card หลีกเลี่ยงการใช้อูเบอร์และรถแท็กซี่ถ้าเป็นไปได้\n                    สำหรับคนที่ชอบปาร์ตี้ ดื่มหรือทานอาหารที่ดี คุณควรเช็คเว็บไซต์ \"eventbrite\" สำหรับบัตรเข้างานฟรีหรือบัตรราคาถูกมากๆ สำหรับงานปาร์ตี้และร้านอาหาร ฉันได้ดูภาพยนตร์มากมายโดยไม่เสียค่าใช้จ่ายด้วยการลงทะเบียนเว็บไซต์ของ Warner Brothers และ Gofobo นอกจากนี้คุณยังสามารถรับบัตรเข้าชมการฉายภาพยนตร์ T.V. ฟรี เช่น Jimmy Kimmel, Ellen Degeners และ iota.com ด้วย นอกจากนี้คุณยังสามารถรับ \"MoviePass\" ทางออนไลน์ได้ในราคา 10 เหรียญต่อเดือนซึ่งช่วยให้คุณสามารถชมภาพยนตร์ได้ไม่จำกัดที่โรงภาพยนตร์ Tekila Bar on Hollywood Walk of Fame ใกล้ Yucca และ Las Palmas มีชั่วโมงแห่งความสุขทุกวัน (ซึ่งคุณสามารถดื่มและทานอาหารในราคาถูกมากๆ) ทุกๆวันจะมีเมนูที่แตกต่างกันไป ถ้าคุณชอบเล่นโบว์ลิ่ง ลองมา \"Pinz bowling\" ในเมืองคัลเวอร์ คุณจ่ายเงิน 8 เหรียญแต่เล่นโบว์ลิ่งได้อย่างไม่จำกัด\n                    สำหรับการช็อปปิ้งผมขอแนะนำให้ไปที่ \"Miniso\" ที่ถนน Hollywood ใกล้กับโรงละครจีน พวกเขาขายเครื่องใช้ที่มีคุณภาพ เช่น ที่เก็บเอกสาร ของที่ระลึก อุปกรณ์อิเล็กทรอนิกส์และอื่นๆ ในราคาที่ถูกมาก\n                    ขอให้สนุกกับ Los Angeles!\""},{id:71,image:"1678977254-1628066349-julia.jpg",campus_name:b,nationality_name:d,title:"Julia - Poland",text:"Julia มาจากคราคูฟ ประเทศโปแลนด์ ซึ่งเธอทำงานเกี่ยวกับธุรกิจนำเข้า ตอนนี้เธออาศัยอยู่ในลอสแอนเจลิสกับสามีและลูกสาวและกำลังศึกษาหลักสูตรธุรกิจ \u002F TOEIC ที่ MLI Hollywood นอกโรงเรียน Julia ชอบไปชายหาดและสำรวจ Los Angeles เธอหวังที่จะเดินทางไปทั่วสหรัฐอเมริกาในอนาคต\n                    \"ฉันเพิ่งเริ่มเรียนที่ MLI เมื่อ 3 สัปดาห์ก่อน แต่ฉันสังเกตเห็นพัฒนาการที่ดีขึ้น ฉันสามารถเข้าใจคนรอบตัวได้ ก่อนหน้านี้ ฉันจะต้องฟังและตั้งใจ เพื่อจะเข้าใจภาษาอังกฤษ\n                    ฉันชอบที่เราพูดภาษาอังกฤษที่โรงเรียนเท่านั้น เป็นเรื่องที่ดีมากเพราะเราไม่ได้พูดภาษาอื่น ที่บ้านฉันพูดโปแลนด์และรัสเซียกับครอบครัวและเพื่อนๆ แต่ที่โรงเรียนฉันสามารถฝึกภาษาอังกฤษได้เยอะ ฉันเรียนรู้คำศัพท์ใหม่ๆในชั้นเรียน นอกชั้นเรียนฉันยังดู Netflix ทุกวันราว 1-1.5 ชั่วโมง ตอนแรกฉันดูด้วยคำบรรยาย แต่แล้วฉันก็รู้ว่าฉันกำลังฝึกอ่านมากกว่าฟัง สัปดาห์ที่แล้วฉันจึงเริ่มดูทีวีโดยไม่มีคำบรรยาย ทีวีช่วยให้ฉันเข้าใจภาษาอังกฤษที่พูดปกติ ฉันยังอ่านหนังสืออีกด้วย\n                    ฉันชอบ MLI ที่เราเป็นเพื่อนกับครูของเรา เราสามารถพูดคุยกับพวกเขาได้ทุกเรื่อง ฉันได้เรียนรู้มากเกี่ยวกับวิถีชีวิตของชาวอเมริกัน ในชั้นเรียนของฉันมีนักเรียนที่มีระดับภาษาอังกฤษสูงกว่าฉัน ซึ่งช่วยฉันได้มาก ฉันอยากแนะนำ MLI ให้กับทุกคน! “"},{id:70,image:"1678977191-1628066610-johanna.jpg",campus_name:b,nationality_name:d,title:"Johanna - Columbia",text:"ก่อนที่ฉันจะมาเรียน ฉันกลัวการพูดภาษาอังกฤษมากๆ ตอนนี้ฉันมั่นใจขึ้นมากที่จะพูดคุยกับคนอื่นๆ\n\n                    Johanna มาจากโคลัมเบีย เธอจบปริญญาโทด้านสุขภาพทางเพศและอนามัยเจริญพันธุ์ เธอเคยทำงานเป็นพยาบาลกับองค์กรพัฒนาเอกชนในช่วง 5 ปีที่ผ่านมา เธอเป็นนักกิจกรรมสตรีนิยมในประเทศของเธอ ซึ่งเธอต่อสู้เพื่อสิทธิสตรี Johanna มาเรียนที่ MLI เมื่อ 2 เดือนที่ผ่านมาเพื่อพัฒนาทักษะภาษาอังกฤษของเธอเพื่อการทำงานและเพื่อตัวเธอเอง เธออยู่ในหลักสูตรระดับกลาง ขั้นสูง\n                    \n                    MLI ให้ความรู้ภาษาอังกฤษและการฝึกปฏิบัติ ตอนนี้ฉันเข้าใจในสิ่งที่ฉันต้องปรับปรุงเช่นการพูดและไวยากรณ์ โดยเฉพาะอย่างยิ่ง past simple การอยู่ที่ MLI เป็นประสบการณ์ที่ดี เพราะฉันได้พบกับเจ้าของภาษามากมาย เช่น ครู และพวกเขาช่วยฝึกความสามารถภาษาอังกฤษของฉัน ฉันได้พบกับนักเรียนหลายคนจากประเทศอื่นๆ ที่ช่วยฝึกฝนฉันตลอดเวลาเช่นกัน\n                    ในชั้นเรียนเราพูดถึงเรื่องทั่วไป เช่น ครอบครัวความสัมพันธ์ การทำงาน สัตว์ สิ่งแวดล้อม ฯลฯ ครูบางคนใช้กิจกรรมที่น่าสนใจ เช่น เกมหรือวิดีโอและมันช่วยได้มาก\n                    ฉันทำสิ่งอื่นๆ เพื่อช่วยพัฒนาภาษาอังกฤษของฉัน หลังเลิกเรียนฉันทำการบ้านจากชั้นเรียน ฉันขอการบ้านเพิ่มเติมจากครู ทุกวันพุธฉันจะเรียนสนทนาฟรีเป็นภาษาอังกฤษที่ห้องสมุดสาธารณะใกล้กับสาขาฮอลลีวูด ฉันดูภาพยนตร์และรายการทีวีเป็นภาษาอังกฤษ ฉันฟังเพลงภาษาอังกฤษและบางครั้งฉันก็ไปเที่ยวกับเพื่อนร่วมชั้นและพูดคุยกัน"},{id:69,image:"1678977123-1628067192-polina.jpg",campus_name:a,nationality_name:d,title:"กิจกรรมหลังเลิกเรียน",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Polina เธอมาจากเกาะ Sakhalin ในรัสเซีย ซึ่งอยู่ใกล้กับประเทศญี่ปุ่นมากๆ (เธอสามารถพูดภาษาญี่ปุ่นได้ด้วย!) ในช่วงเวลาว่าง เธอชอบไปเที่ยวกับเพื่อนๆ ดูภาพยนตร์ ฟังเพลงและถ่ายรูป เธออยู่ที่นี่มา 3 สัปดาห์แล้วและวางแผนที่จะอยู่ต่ออีกเป็นเวลา 3 สัปดาห์ ปัจจุบันเธอกำลังเรียนหลักสูตร IELTS และวางแผนที่จะเรียนต่อมหาวิทยาลัยในประเทศแคนาดา เธออาจศึกษาเศรษฐศาสตร์หรือการตลาด แต่เธอยังไม่แน่ใจ เธอคิดว่าจะสอบ IELTS ใน 2 สัปดาห์และหวังว่าจะได้คะแนน 6.5\n                    \n                    โดยปกติหลังเลิกเรียน ฉันมักจะทบทวนบทเรียนเพื่อเตรียมสอบ IELTS หรือไม่ก็ออกไปกับเพื่อนที่บ้านเพื่อหาสถานที่ใหม่ๆ ฉันชอบไปโรงภาพยนตร์และพิพิธภัณฑ์ใน Los Angeles สถานที่ที่ฉันชอบที่สุดคือ Santa Monica Beach ฉันชอบบรรยากาศมากๆ และฉันก็ชอบไปถนน Melrose เพราะมีร้านค้าสไตล์เก่าๆมากมาย นอกจากนี้ยังมีคาเฟ่และร้านอาหารน่านั่งอีกด้วย ฉันอาศัยอยู่ใกล้ Melrose ในฮอลลีวูด ดังนั้นฉันจึงไปที่นั่นได้ง่ายๆ ฉันคิดว่าฮอลลีวูดเป็นสถานที่ที่ดีในการอาศัยเพราะไม่ค่อยมีคนไร้บ้านมากนัก แต่ห่างไกลจากโรงเรียนนิดหน่อย LA ยังมีสภาพอากาศที่สมบูรณ์แบบ ฉันไปเที่ยวนครนิวยอร์ก สภาพอากาศที่นั่นร้อนและชื้นมาก แต่ลอสแอนเจลิสสบายๆ MLI\n                    \n                    เป็นโรงเรียนที่ดีเพราะเจ้าหน้าที่ช่วยเหลือตลอด รู้สึกสะดวกสบายมากที่มีเจ้าหน้าที่ที่มาจากประเทศของคุณ เพื่อแสดงสิ่งที่คุณรู้สึกหรือต้องการ ฉันสนุกกับที่นี่มากๆ “"},{id:68,image:"1678977059-1628068497-nanami.jpg",campus_name:a,nationality_name:c,title:"สื่งที่ควรทำที่สุดใน Los Angeles",text:"นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Nanami เธอมาจากนาโกย่า ประเทศญี่ปุ่นและอาศัยอยู่ใน Los Angeles เป็นเวลา 7 เดือน ปัจจุบันเธอเรียนหลักสูตร ESL ระดับกลางขั้นสูง เวลาว่างเธอชอบไปเที่ยวชมสถานที่ต่างๆในลอสแอนเจลิสและหาสถานที่ใหม่ ๆ ในการรับประทานอาหารหรือซื้อสินค้า\n\n                    \"ฉันชอบ Los Angeles มากๆ สภาพอากาศที่สมบูรณ์แบบและมีสถานที่ท่องเที่ยวมากมาย สถานที่โปรดของฉันคือ Santa Monica มีคนมากมายที่นั่นและทุกคนดูมีความสุข ชายหาดที่ฉันชอบคือ Malibu ฉันชอบร้านอาหารมากมายที่อยู่ใกล้โรงเรียนใน Westwood สถานที่โปรดของฉันคือ PokeMe ซึ่งอยู่ติดกับโรงเรียน! ฉันชอบร้านพิซซ่า 800 องศาและ In-N-Out ด้วย In-N-Out เป็นเช่นสถานที่คนในแคลิฟอร์เนียโดยทั่วไปชอบกิน! ร้านค้าที่ฉันชอบคือ Sephora ฉันชอบซื้อเครื่องสำอางที่นั่นและ Brandy Melville เพื่อซื้อเสื้อผ้า ฉันอาศัยอยู่ในหอพัก Westwood ซึ่งเป็นที่ที่ดีเพราะเป็นเรื่องง่ายที่จะพบปะผู้คน ฉันไม่เคยเหงาเมื่อฉันอยู่ที่นั่น ซึ่งดีกว่าการเช่าอพาร์ทเม้นด้วยตัวเอง ทุกๆวันฉันสามารถพูดคุยกับเพื่อนร่วมห้องและฝึกทักษะการพูดภาษาอังกฤษได้ และใช้เวลาเดินเพียง 15 นาทีจากโรงเรียน สะดวกมากๆ ฉันชอบ Mentor เพราะครู ฉันมีครูหลายท่านเพราะฉันเริ่มเรียนในระดับปานกลาง ครูทุกคนที่ฉันเคยเรียนด้วยดีมากๆ พวกเขาเป็นส่วนที่ดีที่สุดของโรงเรียนนี้ พวกเขาเป็นคนใจดีและตลกมากๆ ซึ่งจะทำให้ชั้นเรียนสนุกสนาน ฉันขอแนะนำให้ทุกคนมาเรียนที่ MLI! \""},{id:67,image:"1678976961-1628069001-vaclav.jpg",campus_name:b,nationality_name:d,title:"Vaclav - Czech Republic",text:"ดาวเด่นสาขา Hollywood\n\n                    Vaclav มาจาก Turnov สาธารณรัฐเช็ก (100 กิโลเมตรจากปราก) เขาจบการศึกษาจากโรงเรียนมัธยมเมื่อปีที่แล้ว อเมริกาคือความฝันของเขา และตอนนี้เขาก็กำลังเรียนภาษาอังกฤษหลักสูตรขั้นสูงที่ MLI Hollywood\n                    \n                    \"สัปดาห์แรกในอเมริกาเป็นเรื่องยากสำหรับผม ผมมั่นใจ เป็นที่นิยม ออกไปข้างนอกและพูดคุยระหว่างกลับบ้าน แต่ในอเมริกามันแตกต่างไปจากเดิมอย่างสิ้นเชิง ผมขี้อาย, ใจแคบ, และกลัวที่จะพูดคุยกับคนและออกไปข้างนอก ผมหดหู่! ผมไม่เคยรู้สึกแบบนี้มาก่อน พ่อของผมแนะนำว่าผมควรเริ่มเรียนภาษาอังกฤษ เขาคิดว่าผมควรจะอยู่กับคนอื่นและฝึกการพูดภาษาอังกฤษ ผมมองหาโรงเรียนจนพบ Mentor Language Institute อยู่ใกล้กับที่พักและถูกกว่าโรงเรียนอื่น ๆ\n                    \n                    ตั้งแต่วันแรก ผมรู้ว่าผมเลือกโรงเรียนที่เหมาะสม คุณได้รับความสนใจที่ MLI ชั้นเรียนมีขนาดเล็กและครูเน้นนักเรียนแต่ละคน นั่นคือสิ่งที่ผมชอบและชื่นชม ผมเริ่มรู้สึกดีขึ้นเพราะผมคิดได้ว่าการติดต่อกับผู้คนจากทั่วโลกไม่ยากนัก ก่อนที่ฉันจะมา MLI มันยากที่จะเข้าใจเข้าของภาษา เป็นเรื่องตลกมากเพราะผมคิดว่าภาษาอังกฤษของผมค่อนข้างดี แต่เจ้าของภาษาอังกฤษพูดอย่างรวดเร็วและใช้สำนวนและคำแสลงที่ฉันไม่รู้จัก แต่ที่ MLI ครูพูดได้อย่างชัดเจนและใช้คำที่ผมสามารถเข้าใจได้ นั่นทำให้ผมมั่นใจและผมก็เริ่มพูดคุยกับคนนอกโรงเรียนเช่นกัน ฉันเริ่มไปที่ต่างสถานที่เช่นป้าย Hollywood, Griffith Observatory, Santa Monica Pier และอื่นๆ คำแนะนำสำหรับความสำเร็จของผมที่ MLI คือ ถึงแม้ว่าคุณจะกลัว แต่ก็ผลักดันตัวคุณเองและพูดคุยให้มากที่สุดเท่าที่คุณจะทำได้! อย่ากลัวที่จะทำผิดพลาด และในที่สุดการเดินทางคือการใช้ชีวิต ไปดูโลกกันเถอะ! \""},{id:66,image:"1678975220-1628147114-Oguz.jpg",campus_name:a,nationality_name:m,title:"Name: Oguz",text:"ดาวเด่นสาขา Westwood\n\n                    ชื่อ : โอกัส\n                    \n                    สัญชาติ : ตุรกี\n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ?\n                    \n                    ผมเริ่มต้นจากหลักสูตรภาษาอังกฤษทั่วไป ระดับกลาง ขั้นสูง\n                    แล้วก็เลื่อนชั้นไปเรียนระดับสูง และตอนนี้ผมกำลังเรียนหลักสูตร TOEFL\n                    \n                    ทำไมคุณถึงเลือกมาเรียนที่ Los Angeles?\n                    ผมมาอยู่ที่รัฐ Virginia ปีที่แล้ว และมีโอกาสได้แวะมาเที่ยว LA 3 วัน แต่แค่นั้นไม่พอ\n                    ผมพูดกับตัวเองว่า สักวันหนึ่งต้องมาอยู่ที่นี่ให้ได้ และในที่สุด ผมก็ได้มาอยู่ที่นี่แล้ว\n                    มันเป็นที่ดีมากๆ อากาศก็ดีด้วย\n                    \n                    ทำไมคุณถึงเลือก MLI?\n                    เพื่อนของผมคนหนึ่งเคยอยู่ที่นี่บอกว่า มีโรงเรียนที่ดีและน่าทึ่งที่เคยเรียน\n                    เธอบอกว่าทั้งครู ผู้จัดการและเพื่อนนักเรียนน่ารักมากๆ\n                    และความน่ารักนี้สำคัญสำหรับผม เธอพูดถึง MLI ผมจึงตัดสินใจมาตามที่เธอแนะนำ\n                    และผมก็อยู่ที่นี่แล้ว\n                    \n                    ผมตกหลุมรักการแสดงที่นี่ ผมเรียนการแสดงเพื่อพัฒนาทักษะของผม\n                    ผมรักการค้นพบสถานที่ใหม่ๆในทุกๆวัน ใน LA มีสถานที่ที่น่าค้นหามากมาย\n                    มันไม่น่าเบื่อเลย\n                    \n                    คุณพักอยู่ที่ไหนใน Los Angeles คะ? พอจะแนะนำให้กับนักเรียนคนอื่นๆได้ไหม?\n                    ผมอยู่ Westwood ซึ่งใกล้กับหอพักมากๆ\n                    มันดีสำหรับผมเพราะผมได้พบผู้คนมากมาย\n                    การอยู่ที่นั่นทำให้ผมได้พัฒนาทักษะการแสดง เพื่อนผมคนหนึ่งเป็นผู้กำกับ\n                    และอีกคนหนึ่งเป็นช่างภาพ มีนักเรียนมากมายใน Westwood และทุกๆที่ที่คุณไป\n                    \n                    คุณคิดว่าทักษะภาษาอังกฤษของคุณดีขึ้นไหมตั้งแต่คุณย้ายมาที่นี่?\n                    แน่นอน\n                    ผมไม่เคยคิดเลยว่าผมจะสามารถพัฒนาทักษะของผมได้ขนาดนี้\n                    ต้องขอบคุณทั้งครูและเจ้าหน้าที่ที่เข้าใจผมเสมอและช่วยทำให้ทักษ\n                    ะภาษาของผมดีขึ้นด้วย\n                    \n                    คุณมีคำแนะนำอะไรไหมสำหรับนักเรียนที่อยากมาเรียนภาษาในอนาคต?\n                    ถ้าคุณมีความฝัน คุณจะทำทุกอย่างเพื่อมัน อย่างเช่น คุณสามารถเป็นนักเต้นที่ดีที่สุด\n                    นักแสดงที่ดีที่สุด หรือได้รับประสบการณ์ที่ดีที่สุด ทั้งโรงเรียนและครูใน LA\n                    นั้นดีที่สุดในโลก อย่ากลัวที่จะทำมัน\n                    คุณสามารถประสบความสำเร็จได้ในขณะที่คุณอยู่ที่นี่"},{id:65,image:"1678974941-1628147349-Emily.jpg",campus_name:b,nationality_name:e,title:"Name: Emily",text:"ดาวเด่นสาขา Hollywood\n\n                    ชื่อ: เอมมีลี่ ชู\n                    \n                    สัญชาติ: ไต้หวัน\n                    \n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ?\n                    ฉันกำลังเรียนหลักสูตร ESL ค่ะ\n                    \n                    ทำไมคุณถึงเลือกมาเรียนที่ LA?\n                    ฉันรักแคลิฟอร์เนีย และฮอลลีวูดเป็นเมืองที่สะดวกมากๆ ที่สำคัญมีแสงแดดตลอดเวลา\n                    \n                    ทำไมคุณถึงเลือกมา MLI?\n                    ราคาค่าเรียนของ MLI ถูกและครูก็สอนดีมากๆ\n                    ฉันค้นหาข้อมูลมากมายเกี่ยวกับโรงเรียนบนอินเทอร์เน็ต\n                    และฉันได้พูดคุยกับตัวแทนในไต้หวัน ไฮเวเป็นผู้จัดการที่สาขาฮอลลีวูด\n                    และเขาได้ช่วยเหลือฉันมากมาย\n                    \n                    ภาษาอังกฤษของคุณเป็นอย่างไรบ้างก่อนที่คุณได้เรียนที่นี่?\n                    ระดับภาษาอังกฤษของฉันแย่มากๆ ฉันไม่เข้าใจอะไรเลย\n                    ฉันไม่สามารถแม้แต่จะสั่งกาแฟหรือไปตลาด\n                    ฉันอยากถามบางอย่างแต่ก็ไม่รู้ต้องพูดอย่างไร\n                    \n                    ค่ะ ตอนนี้ฉันเข้าใจเจ้าของภาษา ฉันสามารถพูดคุยและถามคำถามได้เช่นกัน\n                    \n                    มีอะไรอยากบอกนักเรียนคนอื่นๆไหม?\n                    สนุกกับการเป็นนักเรียน ทำให้ดีที่สุดและพูดภาษาอังกฤษ"},{id:64,image:"1678974444-1628147734-Fumiya.jpg",campus_name:a,nationality_name:c,title:"สถานที่ดีมากๆ (ฟูมิยะ | ญี่ปุ่น)",text:"ฟูมิยะเข้าศึกษาในระดับชั้น Beginning 2 ที่ MLI สาขา Westwood เจ้าหน้าที่ทุกคนเป็นมิตรและการเรียนเป็นประโยชน์มาก\n                    ที่ตั้งของโรงเรียนก็เยี่ยมมากเช่นกัน\n                    Westwood มีสถานที่เจ๋งๆมากมายที่ควรไปและร้านค้าจำนวนมากสำหรับขาช็อป\n                    ครูของฉันช่วยเหลือและใช้เวลาในการอธิบายคำถามทั้งหมดของฉัน\n                    ฉันยังชอบที่มีความหลากหลายของนักเรียนที่นี่ เพราะฉันมีโอกาสที่จะได้ทำความรู้จักกับเพื่อนใหม่จากทั่วทุกมุมโลก"},{id:61,image:"1678968535-1628148128-Martin.jpg",campus_name:b,nationality_name:d,title:"ฉันสามารถพัฒนาทักษะภาษาอังกฤษของฉันได้อย่างรวดเร็ว (มาติน | สาธารณรัฐเช็ก)",text:"มาตินเข้าศึกษาระดับชั้น Intermediate 2 ที่ MLI สาขา Hollywood\n                    ผมมา Los Angeles เพื่อเรียนภาษาอังกฤษและผมก็มีความสุขมากที่ได้พบกับ MLI ที่นี่เป็นโรงเรียนที่น่าทึ่งและมีครูที่ดีมากมาย ผมอยู่ที่นี่แค่เดือนเดียว แต่ผมได้เรียนรู้มากกว่าที่ผมเคยคิดไว้\n                    ขอบคุณ!!\n                    \n                    และผมก็รู้สึกว่า MLI มีหลักสูตรที่ดีด้วยเช่นกัน ผมเริ่มต้นหลักสูตร ESL ระดับ Beginner 1 ครูของผมสอนดีมากจริงๆ ดังนั้นผมจึงสามารถพัฒนาทักษะภาษาอังกฤษได้อย่างรวดเร็ว นั่นเป็นแรงกระตุ้นที่ดีมากๆ ผมคิดว่าจะเรียน TOEFL® ที่ MLI เพราะ MLI จะพัฒนาทักษะต่างๆ ในการเข้าศึกษาต่อระดับมหาวิทยาลัยในสหรัฐฯ"},{id:60,image:"1678968363-1628148669-Victor.jpg",campus_name:a,nationality_name:f,title:"MLI ให้ความรู้ภาษาอังกฤษมากมายที่ต้องนำไปใช้ในการเข้ามหาวิทยาลัย ในประเทศสหรัฐอเมริกา (จาว วิคเตอร์ | บราซิล)",text:"จาวเข้าศึกษาระดับชั้น High Intermediate 2 ที่ MLI สาขา WESTWOOD\n                    ผมชอบ MLI ด้วยเหตุผลหลายประการ อย่างแรกสถานที่ตั้ง โรงเรียนนี้ตั้งอยู่ในแคลิฟอร์เนีย ซึ่งอากาศดีมากๆ และเป็นสถานที่ที่สวยงาม\n                    อย่างที่สอง ผมรู้สึกว่าหลักสูตรที่นี่ดีมาก ผมเริ่มเรียนตั้งแต่ระดับเริ่มต้นและเนื่องจากครูของผมยอดเยี่ยมมาก ผมจึงเลื่อนชั้นและพัฒนาภาษาอังกฤษได้อย่างรวดเร็ว\n                    ผมวางแผนที่จะเรียน TOEFL® ที่นี่เช่นกัน และผมรู้ว่า MLI จะช่วยพัฒนาทักษะภาษาอังกฤษที่จำเป็นในการเข้าเรียนต่อระดับมหาวิทยาลัยในอเมริกา ซึ่งเป็นความฝันของผม"},{id:59,image:"1678968189-1628148897-hani.jpg",campus_name:a,nationality_name:k,title:"ผมได้เรียนหลักสูตร GRE\u002FGMAT สำหรับเตรียมตัวศึกษาระดับบัณฑิตวิทยาลัย (ฮานิ | ซาอุดิอารเบีย)",text:"ฮานิเข้าศึกษาหลักสูตร GRE\u002FGMAT ที่ MLI สาขา Westwood\n                    วันแรกที่มาถึง MLI ทุกคนยิ้มแย้มและเป็นมิตรกับผมมาก ผมรู้สึกดีใจที่ได้เลือกโรงเรียนแห่งนี้เพื่อพัฒนาภาษาอังกฤษและเตรียมตัวสำหรับการศึกษาระดับบัณฑิตศึกษา โดยการเข้าเรียนหลักสูตร GRE®\u002FGMAT® ครูและเจ้าหน้าที่เป็นมิตรมากและผมอยากแนะนำให้โรงเรียนนี้กับทุกคนเป็นอย่างมาก\n                    ขอบคุณมากครับ"},{id:58,image:"1678965970-1628149121-Maria2.jpg",campus_name:a,nationality_name:d,title:"ฉันได้พบเพื่อนใหม่มากมายที่นี่ (มาเรีย | เวเนซุเอลา)",text:"มาเรียเข้าศึกษาระดับชั้น Intermediate 1 ที่ MLI สาขา Westwood\n                    Mentor Language Institute เป็นโรงเรียนที่มีชื่อเสียงที่ดี เจ้าหน้าที่ทุกคนใจดีและช่วยเหลือฉันเสมอ และฉันไม่พบปัญหาใดๆ ในขณะที่ฉันอยู่ที่นี่ ซึ่งมันยอดเยี่ยมมาก ครูก็ช่วยเหลือฉันมากเช่นกัน พวกเขาช่วยแก้ไขความขี้อายของฉันเมื่อฉันมาถึงครั้งแรก พวกเขายังสนับสนุนให้ฉันถามคำถามมากมายซึ่งช่วยพัฒนาภาษาอังกฤษของฉัน ฉันมีเพื่อนใหม่มากมายที่นี่ ขอบคุณเจ้าหน้าที่ทุกคน พวกคุณยอดเยี่ยมมากและครูผู้สอนเช่นกันและฉันก็รู้สึกขอบคุณสำหรับทุกสิ่ง"},{id:48,image:"1628149365-Saori.jpg",campus_name:b,nationality_name:c,title:"มาสนุกกับเราพร้อมพัฒนาทักษะภาษาอังกฤษในเวลาเดียวกัน (ซาโอริ | ญี่ปุ่น)",text:"ซาโอริเข้าศึกษาหลักสูตร Conversation ระดับ Advance ที่ MLI สาขา Hollywood\n                    ฉันเรียนที่ MLI ซึ่งตั้งอยู่ที่ Hollywood เป็นเวลา 1 ปี 5 เดือน\n                    ในช่วงเวลานั้น ฉันได้รับประสบการณ์ที่ดีหลายอย่างมากกว่าที่ฉันเคยจินตนาการ ฉันดีใจมากที่ได้มาเรียนที่ MLI เมื่อฉันมาที่นี่ฉันไม่สามารถพูดภาษาอังกฤษได้เลย แต่ตอนนี้ฉันรู้สึกว่าทักษะภาษาอังกฤษของฉันดีขึ้นมากๆ เพราะครูและเพื่อนๆ ที่ฉันพบใน MLI ครูช่วยและสอนภาษาอังกฤษให้ฉันเสมอ ดีจนเข้าใจได้อย่างชัดเจน\n                    พวกเขาไม่ได้สอนฉันแค่ภาษาอังกฤษ แต่รวมถึงวัฒนธรรมต่างๆของอเมริกาด้วย นอกจากนี้พวกเขายังเป็นมิตรมากๆ เจ้าหน้าทีทุกคนช่วยฉันเสมอเมื่อฉันมีข้อข้องใจ\n                    \n                    อีกเหตุผลหนึ่งที่ฉันชอบ MLI ก็คือแต่ละชั้นเรียนมีขนาดเล็ก ซึ่งหมายความว่าการทำความรู้จักกับเพื่อนจึงเป็นเรื่องง่าย\n                    นักเรียนจำนวนมากมาจากประเทศต่างๆ ถ้าฉันไม่ได้มา MLI ฉันอาจจะไม่ได้เรียนรู้เกี่ยวกับวัฒนธรรมที่แตกต่างและได้พบปะผู้คนจากทั่วโลก\n                    มันทำให้ฉันทำครบ 180 ในชีวิตของฉัน\n                    ถ้าโรงเรียนน่าเบื่อ ฉันคงจะไม่พอใจกับชีวิตของฉันในแอลเอ\n                    เป็นความยินดีที่ได้พบกับทุกคนที่นี่ ถ้าคุณยังลังเลที่จะมาที่ LA ฉันจะบอกคุณว่า \"\"ทำมันซะ!\"\"\n                    มาสนุกกับเราพร้อมพัฒนาทักษะภาษาอังกฤษของคุณให้ดีขึ้นไปพร้อมๆกัน"},{id:40,image:"1628146867-Sofia.jpg",campus_name:a,nationality_name:h,title:"Name: Sofia",text:"ชื่อ : โซเฟีย\n                    สัญชาติ : รัสเซีย\n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ?\n                    ฉันเรียนหลักสูตร TOEFL ช่วงเย็น ฉันกำลังวางแผนเรียนหลักสูตรเสริมที่ UCLA ในอนาคตและต้องใช้คะแนน\n                    TOEFL ฉันอยากเรียนภาษาต่อใน Los Angeles หลังจบจากที่นี่ เพื่อพัฒนาทักษะของฉันมากยิ่งขึ้น\n                    ทำไมคุณถึงตัดสินใจมา Los Angeles?\n                    ฉันรักแคลิฟอเนียร์ อากาศที่นี่ดีมาก LA เป็นสถานที่ที่ดีที่สุดในการเรียนรู้ความหลากหลายทางวัฒนธรรม\n                    นอกจากนี้ยังมีสถานที่ธรรมชาติที่น่าสนใจ LA เหมือน New York แต่อบอุ่น\n                    คุณชอบทำกิจกรรมอะไรใน LA?\n                    ฉันรักทะเลและเล่นเซิร์ฟ\n                    มันดีมากที่คุณสามารถไปทะเลและขับรถแค่ 2 ชั่วโมงไปเล่นสกีต่อ หรือไปสวนสาธารณะเพื่อขี่จักรยาน\n                    ถ้าคุณเป็นคนเสพติดกีฬา คุณสามารถหาทุกอย่างได้ที่นี่\n                    ทำไมคุณถึงเลือก MLI?\n                    ที่จริงแล้วฉันใช้เวลากว่าเดือนเพื่อหาโรงเรียน แต่คุณรู้ไหม การช็อปปิ้งใน LA ทำให้ฉันพบโรงเรียนที่ดีที่สุดสำหรับฉัน\n                    และในที่สุดฉันก็พบ MLI คุณภาพและราคาเหมาะสม มันดีมากสำหรับฉัน\n                    คุณรู้สึกไหมว่าทักษะภาษาอังกฤษของคุณดีขึ้นตั้งแต่คุณมา LA?\n                    แน่นอน! ฉันเพิ่งเรียนที่นี่ได้แค่ 2 สัปดาห์ แต่มีการเปลี่ยนแปลงหลายอย่าง ฉันลืมสิ่งที่เคยได้เรียนมา\n                    และได้เรียนรู้อะไรใหม่ๆหลายอย่าง โดยเฉพาะอย่างยิ่งคำศัพท์ ฉันสามารถบอกได้เลยว่าฉันพูดได้ดีกว่าแต่ก่อน\n                    \n                    คุณพักอยู่ที่ไหนใน LA? คุณแนะนำที่พักให้กับนักเรียนใหม่ได้ไหม?\n                    ฉันอาศัยอยู่ใน Bel Air ฉันชอบที่นี่มาก ฉันคิดว่ามันดีสำหรับการพักอาศัย ถึงแม้ราคาค่อนข้างสูง\n                    แต่ฉันเช่าห้องในบ้านหลังใหญ่ มันดีสำหรับฉันจริงๆ"},{id:39,image:"1628146649-marina.jpg",campus_name:a,nationality_name:c,title:"Name: Marina",text:"Marina\n\n                    【The reason of Study Abroad・Background・Goals】\n                    เหตุผลของการศึกษาต่อต่างประเทศ · ความเป็นมา · เป้าหมาย\n                    ตอนที่ฉันยังเรียนอยู่ระดับประถมศึกษา\n                    แม่และฉันเคยดูภาพยนตร์ของอเมริกันด้วยกันบ่อยๆ ซึ่งทำให้ฉันสนใจวัฒนธรรมของอเมริกัน\n                    ฉันอยากจะไปอเมริกาเพื่อเรียนรู้วัฒนธรรมเพิ่มเติม\n                    ฉันได้ไปเรียนที่สหราชอาณาจักรในหลักสูตรการศึกษาระยะสั้น\n                    ในขณะที่ฉันอยู่ในโรงเรียนมัธยมและประสบการณ์นี้ทำให้ฉันอยากอยู่ต่างประเทศอีกต่อไป\n                    เพื่อที่ฉันจะได้เรียนรู้วัฒนธรรมได้มากยิ่งขึ้น นี่เป็นเหตุผลที่ฉันตัดสินใจที่จะมาเรียนที่ Los Angeles\n                    \n                    【Why did you choose MLI?】\n                    \n                    คุณเลือก MLI ได้อย่างไร?\n                    ครั้งแรกที่ฉันได้พูดคุยกับตัวแทนบริษัทการศึกษาต่อต่างประเทศเกี่ยวกับสถานที่\n                    ความสำคัญและทักษะภาษาอังกฤษของฉัน เขาเสนอโรงเรียนต่างๆให้ฉัน\n                    เพื่อเลือกโรงเรียนที่เหมาะสมสำหรับฉันที่สุด ฉันสนใจเรื่องคุณภาพและราคา และมีเพียง MLI\n                    เท่านั้นที่เหลืออยู่ในรายการของฉัน\n                    \n                    【What were you worried or concerned about before\n                    coming to LA?】\n                    \n                    คุณมีความกังวลอะไรไหมก่อนที่จะมาที่ LA?\n                    ฉันกังวลเกี่ยวกับความสามารถทางภาษาอังกฤษของฉัน\n                    ตั้งแต่ฉันรู้สึกว่าฉันเป็นคนเดียวที่ไม่เข้าใจอะไรที่โรงเรียนในสหราชอาณาจักรเลย\n                    ในขณะที่นักเรียนคนอื่นพูดภาษาอังกฤษได้อย่างคล่องแคล่ว แต่ฉันไม่\n                    นอกจากนี้ฉันเคยได้ยินจากสื่อทางสังคมว่า LA อันตรายกว่าญี่ปุ่น\n                    ดังนั้นฉันจึงกลัวว่าบางสิ่งบางอย่างน่ากลัวอาจเกิดขึ้นใน LA\n                    \n                    【One word to explain MLI】\n                    \n                    หนึ่งคำเพื่ออธิบาย MLI\n                    ผู้สอนและเจ้าหน้าที่ที่ MLI เป็นน่ารักและเป็นกันเองกับฉัน\n                    ฉันสามารถบอกความคิดเห็นและถามคำถามบางอย่างได้ ไม่ใช่แค่เรื่องเกี่ยวกับโรงเรียน\n                    \n                    แต่พวกเขายังให้คำแนะนำเกี่ยวกับสถานที่ที่ดีและเคล็ดลับในการใช้ชีวิตใน LA\n                    นอกจากนี้ยังมีนักเรียนญี่ปุ่นที่โรงเรียนด้วย ดังนั้นเราทุกคนจึงช่วยเหลือซึ่งกันและกันเมื่อต้องการ\n                    เช่น การแชร์ข้อมูลและการช่วยกันทำการบ้าน\n                    \n                    【How were your studies at MLI?】\n                    \n                    การเรียนของคุณที่ MLI เป็นอย่างไรบ้าง?\n                    ฉันเริ่มต้นจากชั้นเรียนที่อ่อนที่สุด เพราะฉันไม่สามารถใช้ภาษาอังกฤษได้เลย\n                    แต่ครูทุกคนก็พยายามสอนอย่างหนัก เพื่อที่จะเข้าใจว่าฉันต้องการสื่อสารอะไร\n                    ในชั้นเรียนเราจะเรียนการพูด การอ่านและไวยากรณ์\n                    ฉันรู้สึกว่าคนญี่ปุ่นมีความสามารถทางด้านไวยากรณ์ แต่ไม่ค่อยพูด\n                    \n                    【What did you think about the school’s amenities and\n                    location?】\n                    \n                    คุณคิดอย่างไรเกี่ยวกับสิ่งอำนวยความสะดวกและสถานที่ของโรงเรียน?\n                    ฉันคิดว่าโรงเรียนสะอาดและมีระเบียบ ห้องเรียน ห้องนั่งเล่นและห้องสุขาสะอาดตลอดเวลา\n                    คอมพิวเตอร์ ตู้จำหน่ายน้ำและขนม ตู้เย็น ไมโครเวฟและน้ำดื่ม\n                    ได้จัดไว้สำหรับนักเรียนทุกคนในห้องรับรอง นักเรียนจึงสามารถเพลิดเพลินไปกับเวลาพักได้ที่นั่น\n                    นอกจากนี้ MLI ตั้งอยู่ในสถานที่ที่สมบูรณ์แบบพร้อมด้วยจุดชมวิวและร้านอาหารหลายประเภท\n                    ในฐานะนักเรียนฉันสามารถไปเที่ยวชมสถานที่หลังเลิกเรียนและเรียนรู้วัฒนธรรมที่ร้านอาหารต่าง\n                    ๆ\n                    \n                    【What do you like to do in your free time?】\n                    \n                    คุณชอบทำอะไรในช่วงเวลาว่าง?\n                    MLI มีกิจกรรมที่น่าสนใจ เช่น คริสมาสต์ Thanksgiving วาเลนไทน์และงานเลี้ยงจบการศึกษา\n                    ในงานฮาโลวีน นักเรียน ครูและเจ้าหน้าที่ แต่งกายแปลกๆ เพื่อความสนุกสนาน หาด Santa Monica\n                    อยู่ใกล้ MLI ดังนั้นฉันจึงไปที่นั่นในวันสุดสัปดาห์ อากาศดีมากในแอลเอ\n                    ดังนั้นฉันจึงเดินเล่นริมชายหาดและอาบแดดด้วยความ \"California\"\n                    \n                    【What was difficult in LA?】\n                    \n                    มีอะไรที่ยากลำบากไหมใน LA?\n                    ฉันสับสนและมีช่วงเวลาที่ลำบากในการเดินทางไปซูเปอร์มาร์เก็ต\n                    นั่งรถประจำทางและรถไฟใต้ดินเนื่องจากมีความต่างจากประเทศญี่ปุ่นอย่างสิ้นเชิง\n                    สิ่งที่ทำให้ฉันรู้สึกผิดหวังก็คือฉันไม่สามารถพูดภาษาอังกฤษได้อย่างคล่องแคล่วเมื่อฉันต้องการคว\n                    ามช่วยเหลือจากบางคน นั่นทำให้ฉันไม่อยากออกไปข้างนอก สิ่งเหล่านั้นไม่ได้เกิดขึ้นกับฉัน\n                    แต่นักเรียนบางคนรู้สึกคิดถึงบ้านและพลาดอาหารญี่ปุ่นเป็นจำนวนมาก\n                    \n                    【Any special episode while you were in LA?】\n                    \n                    มีช่วงเวลาพิเศษตอนที่คุณอยู่ที่ LA ไหม?\n                    วัฒนธรรมของสตรีสมัยก่อน ฉันรู้สึกประทับใจมากที่ผู้ชายเปิดประตูให้ผู้หญิงทุกครั้งที่ขึ้นรถ\n                    สิ่งที่ฉันประทับใจมากที่สุดก็คือตอนที่บริกรที่ร้านอาหารกำลังจะเติมน้ำให้ผู้ชายคนหนึ่ง\n                    เขาตระหนักว่ามีแก้วเปล่าสำหรับสุภาพสตรีและเขาก็หยุดให้บริการกับชายคนนี้และเริ่มให้บริการผู้\n                    หญิงคนแรก มันไม่เคยเกิดขึ้นในญี่ปุ่น ในฐานะผู้หญิงฉันรู้สึกประทับใจมาก\n                    แต่ฉันไม่รู้ว่าผู้ชายจะคิดอย่างไร\n                    \n                    【How is your English improved after coming to LA?】\n                    \n                    ภาษาอังกฤษของคุณดีขึ้นไหมหลังจากมาที่ LA?\n                    ขณะที่ฉันอยู่ใน LA เพื่อนของฉันก็มาหาฉัน เมื่อเราไปช้อปปิ้งและเที่ยวด้วยกัน\n                    ฉันก็แปลทุกสิ่งทุกอย่างให้เธอและเธอบอกว่าเธอรู้สึกภาคภูมิใจกับฉันด้วยเหตุนี้\n                    นี่เป็นช่วงเวลาที่ฉันรู้สึกว่าภาษาอังกฤษของฉันดีขึ้น แต่ฉันไม่ได้มีความมั่นใจเกี่ยวกับเรื่องนี้\n                    คำพูดของเธอมีความหมายกับฉันมาก\n                    \n                    【What did you earn other than English?】\n                    \n                    คุณมีได้รับอะไรอีกบ้างนอกเหนือจากภาษาอังกฤษ?\n                    เพื่อน ฉันพยายามจะสนิทสนมกับชาวต่างชาติเพื่อที่ฉันจะได้พูดภาษาอังกฤษเป็นประจำทุกวัน\n                    ฉันมีเพื่อนสนิทมากมายในตอนท้าย ไม่มีใครพูดภาษาอังกฤษได้คล่อง แต่เราใช้เวลาไปเที่ยว\n                    ช้อปปิ้ง รับประทานอาหารกลางวันและปาร์ตี้กันและเราสนุกมาก\n                    พวกเขามีความหมายกับฉันมากและตอนนี้ฉันนึกไม่ออกเลยว่าชีวิตของฉันโดยที่ไม่มีพวกเขาจะเป็\n                    นอย่างไร"},{id:38,image:"1628146419-Anastasiia.jpg",campus_name:b,nationality_name:h,title:"Name: Stacy",text:"ดาวเด่นสาขา Hollywood\n                    ชื่อ : อนาสตาเซีย (สเตซี่)\n                    สัญชาติ : รัสเซีย\n                    \n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ?\n                    \n                    ฉันกำลังเรียนหลักสูตรภาษาอังกฤษทั่วไป\n                    เพราะว่าฉันอยากเรียนทักษะพื้นฐานภาษาอังกฤษ ฉันชอบหลักสูตรนี้มากๆ\n                    หนังสือที่เรียนก็ดีมากๆ มันช่วยฉันได้เยอะเลย\n                    \n                    ทำไมถึงเลือก MLI?\n                    ฉันเลือกที่นี่เพราะ LA เป็นศูนย์กลางของโลก Hollywood เป็นศูนย์กลางของ California\n                    และ MLI เป็นศูนย์กลางของ Hollywood\n                    \n                    คุณชอบทำอะไรเวลาว่าง?\n                    ฉันชอบธรรมชาติ ฉันจึงไปทะเลและเดินป่าอยู่บ่อยๆ\n                    ฉันได้พบผู้คนที่น่าสนใจทุกที่ที่ไปเพราะคนเหล่านั้นมาที่นี่เพื่อทำฝันให้เป็นจริง\n                    สิ่งนี้ทำให้ LA พิเศษและน่าทึ่งสุดๆ\n                    \n                    คุณได้เรียนรู้อะไรบ้างเมื่อคุณมาอยู่ LA?\n                    ฉันได้รับประสบการณ์มากมายที่นี่\n                    ซึ่งประสบการณ์เหล่านี้ทำให้ฉันโตและแข็งแกร่งขึ้นกว่าเดิม\n                    \n                    ทักษะภาษาอังกฤษของคุณดีขึ้นไหมหลังจากมาอยู่ที่นี่?\n                    \n                    ค่ะ ฉันอยู่ที่นี่ได้ 6 เดือนแล้วและฉันได้เห็นการเปลี่ยนแปลงครั้งใหญ่\n                    ฉันเริ่มเรียนตั้งแต่ห้องเรียนระดับเริ่มต้นและตอนนี้ฉันอยู่ในระดับกลาง 2\n                    ตอนนี้ฉันเข้าใจที่ทุกคนพูด การพูดของฉันก็ดีขึ้นและดีขึ้นเรื่อยๆทุกวัน"},{id:37,image:"1628146224-Miki3.jpg",campus_name:a,nationality_name:c,title:"Name: Miki",text:"Miki\n\n                    ประวัติ\n                    นี่เป็นปีที่สามของฉันในฐานะพนักงานเต็มเวลา\n                    หลังจากจบการศึกษาจากมหาวิทยาลัย\n                    ฉันทำงานเป็นนักออกแบบงานแต่งงานและแต่งหน้าเป็นเวลา 2 ปีครึ่ง\n                    ถึงแม้ฉันจะเรียนด้านชีววิทยาและเคมี\n                    ซึ่งแตกต่างไปจากการบริการลูกค้าอย่างสิ้นเชิง ในขณะที่อยู่ในมหาวิทยาลัย\n                    ฉันสนใจที่จะศึกษาในต่างประเทศ แต่พ่อแม่ของฉันไม่เห็นด้วยกับเรื่องนี้\n                    เพราะฉันไม่มีเหตุผลที่ชัดเจนมากพอ ฉันยอมแพ้กับความฝันนี้\n                    หลังจากการทำงานหลายปี ฉันหันมาสนใจเกี่ยวกับศาสนา\n                    วัฒนธรรมและภาษามากขึ้น ดังนั้นฉันจึงออกจากงานและ 4 ปีต่อมาฉันจึงมา Los\n                    Angeles เพื่อการศึกษา\n                    \n                    คุณทำอะไรก่อนที่จะมาที่ LA?\n                    ในปีแรกที่งานแต่งงาน\n                    ฉันทำงานที่กินซ่าที่ที่ชาวญี่ปุ่นและชาวต่างชาติมาวางแผนจัดงานแต่งงานของพวกเ\n                    ขา อย่างไรก็ตามฉันไม่สามารถสื่อสารกับพวกเขาได้ดีเพราะภาษาอังกฤษของฉัน\n                    \n                    ด้วยเหตุนี้ฉันจึงเริ่มเรียนภาษาอังกฤษอย่างจริงจัง\n                    ที่จริงฉันได้สมัครงานที่บริษัทสายการบินเมื่อฤดูร้อนที่ผ่านมา\n                    แต่น่าเสียดายที่ฉันไม่ได้รับการยอมรับ ฉันได้สัญญากับตัวเองว่าจะไปอเมริกา\n                    ถ้าไม่ได้รับการยอมรับในครั้งนี้\n                    บริษัทต่างชาติทุกแห่งในญี่ปุ่นต้องใช้ทักษะภาษาอังกฤษระดับสูง\n                    ดังนั้นฉันจึงถูกบังคับให้ยอมแพ้ ฉันหวังว่าฉันจะได้\n                    แต่เพราะภาษาอังกฤษที่แย่ของฉัน จากประสบการณ์การศึกษาในต่างประเทศ\n                    ฉันอยากเรียนภาษาที่ฉันสามารถมีส่วนร่วมในหลายๆวัฒนธรรม\n                    เพื่อที่ฉันจะสามารถทำให้ตัวเองพบกับความท้าทายอื่นๆอีก\n                    \n                    ทำไมคุณถึงเลือก MLI? คุณกำลังมองหาโรงเรียนแบบไหน?\n                    เมื่อฉันสมัครงานที่บริษัทสายการบินในประเทศญี่ปุ่น พวกเขาต้องการคะแนน TOEIC\n                    เพื่อพิสูจน์ความสามารถทางภาษาอังกฤษของฉัน ฉันดิ้นรนเพื่อพัฒนาคะแนนของฉัน\n                    ดังนั้นฉันจึงไปโรงเรียนที่เน้นและเชี่ยวชาญเฉพาะเกี่ยวกับ TOEIC เป็นเวลา 3 เดือน\n                    โรงเรียนนี้มีกลยุทธ์การสอนแบบเดียวกับ MLI\n                    โรงเรียนที่ฉันเรียนในญี่ปุ่นพอดีกับฉันมาก แต่ MLI มี ESL, การสนทนาภาษาอังกฤษ,\n                    ธุรกิจ, TOEIC, TOEFL และ IELTS ฉันเลือก MLI\n                    เพื่อที่ฉันจะได้ใช้ประโยชน์จากหลักสูตรทั้งหมด นอกจากนี้\n                    ฉันรู้สึกกังวลมากเกี่ยวกับเดินทางไปอเมริกา แต่น่าเหลือเชื่อเมื่อพบว่า MLI\n                    มีเจ้าหน้าที่ชาวญี่ปุ่น\n                    \n                    ประสบการณ์ของคุณกับ MLI เป็นอย่างไร?\n                    \n                    ฉันคิดว่าการศึกษาในต่างประเทศจะยากกว่านี้และรู้สึกเหมือนบางสิ่งบางอย่างที่แตก\n                    ต่างกัน แต่ฉันรู้สึกเหมือนอยู่บ้านตลอดเวลาที่ LA ต้องขอบคุณ MLI นักเรียนทุกคนมา\n                    LA ด้วยการต่อสู้ของพวกเขา\n                    แต่พวกเขาก็มาพร้อมกับความปรารถนาที่จะพัฒนาภาษาอังกฤษ\n                    และไม่มีความแตกต่างระหว่างอายุหรือสัญชาติ ฉันเรียน ESL\n                    ในตอนเช้าและเรียนสนทนาในช่วงบ่าย ดังนั้นฉันมักจะอยู่โรงเรียนตลอดทั้งวัน\n                    (หัวเราะ) มีนักเรียนญี่ปุ่นหลายคนในชั้นเรียนตอนเช้า แต่มีบ้างในตอนบ่ายและค่ำ\n                    หากคุณต้องการเรียนที่ไม่มีนักเรียนญี่ปุ่นจำนวนมาก\n                    คุณสามารถจัดชั้นเรียนตามที่คุณต้องการได้และนี่เป็นข้อได้เปรียบอย่างหนึ่งสำหรับ\n                    การเรียนที่ MLI\n                    \n                    คุณชอบสถานที่ของ MLI อย่างไร?\n                    MLI สะอาดและล้อมรอบไปด้วยร้านอาหาร คาเฟ่ ร้านขายยา CVS\n                    และธนาคารต่างๆ\n                    เพื่อให้คุณสามารถใช้ชีวิตได้อย่างสะดวกสบายโดยไม่มีปัญหาใดๆ\n                    เพื่อนของฉันที่ศึกษาในต่างประเทศเคยบอกฉันว่าไม่สะดวกที่จะอาศัยอยู่ในอเมริกาโ\n                    ดยไม่มีรถ แต่ตอนนี้เรามี Uber และ Lyft ซึ่งเหมือนกับรถแท็กซี่ที่ญี่ปุ่น, นก\n                    (สกู๊ตเตอร์), รถโดยสารประจำทางและรถไฟฟ้าใต้ดินที่\n                    ฉันไม่เคยมีปัญหากับการเดินทางที่นี่และมีซูเปอร์มาร์เก็ตญี่ปุ่นอยู่ใกล้ MLI\n                    ดงนั้นฉันจึงสามารถปรุงอาหารญี่ปุ่นได้เช่นกัน\n                    \n                    คุณชอบทำอะไรเวลาว่าง?\n                    ฉันเคยอยู่ในหอพักของโรงเรียนเป็นเวลา 3\n                    สัปดาห์และตอนนี้ฉันอาศัยอยู่ในบ้านร่วมกับชาวอเมริกัน เกาหลี เยอรมันและอิหร่าน\n                    \n                    พวกเขาพูดภาษาอังกฤษได้อย่างคล่องแคล่ว ดังนั้นพวกเขาจึงกระตุ้นฉันอย่างมาก\n                    พวกเขามักจะมาหาฉันและพูดว่า \"มิกิ มาฝึกกันเถอะ\"\n                    และพวกเขาก็สอนภาษาอังกฤษด้วยการพูด,\n                    ดูหนังด้วยกันในเวลากลางคืนและออกไปเที่ยว เพื่อนชาวเกาหลีของฉันและฉันไปที่\n                    San Clemente State Beach ด้วยกันและเราสนุกมาก เมื่อฉันอยู่คนเดียว\n                    ฉันมักจะไปยิมหรือร้านกาแฟเพื่ออ่านหนังสือหรือเรียน\n                    \n                    มีอะไรที่น่าสนใจเกิดขึ้นกับคุณใน LA?\n                    หลังจากผ่านไป 2 สัปดาห์ใน LA\n                    กระเป๋าสตางค์และหนังสือเดินทางของฉันถูกขโมยไปและนี่เป็นเรื่องที่น่าตกใจอย่างยิ่\n                    งสำหรับฉัน\n                    ฉันออกไปกับเพื่อนชาวญี่ปุ่นไปยังที่ที่ผู้คนมากมายและมีคนเปิดกระเป๋าเป้สะพายหลัง\n                    และขโมยของของฉัน\n                    ฉันไม่รู้จริงๆว่าเพิ่งเกิดอะไรขึ้นและเป็นกังวลว่าฉันจะกลับไปญี่ปุ่นได้\n                    แม้ว่าฉันเพิ่งมาถึง 2 สัปดาห์ก่อนและไม่สามารถพูดภาษาอังกฤษได้เลย\n                    ฉันต้องไปที่สถานีตำรวจเพียงคนเดียวและแจ้งความเพื่อขอหนังสือเดินทางและบัตรเ\n                    ครดิตใหม่ ประสบการณ์นี้เป็นประสบการณ์ที่หนักที่สุดที่เคยเกิดขึ้นในชีวิตของฉัน\n                    อย่างไรก็ตามฉันสามารถเติบโตและเรียนรู้ที่จะเอาชนะปัญหาด้วยประสบการณ์นี้\n                    โปรดใช้ความระมัดระวังและให้ความสนใจกับสิ่งของของคุณตลอดเวลา! (หัวเราะ)\n                    \n                    ภาษาอังกฤษของคุณดีขึ้นอย่างไรเมื่อได้มาเรียนในต่างประเทศ?\n                    \n                    ถึงแม้ว่าฉันมาอยู่ LA ได้ 3 เดือน แต่ฉันก็ไม่มีปัญหากับการสนทนา อย่างไรก็ตาม\n                    ถึงมันยังยากเล็กน้อยสำหรับฉันที่จะพูดเมื่อเราเรียนรู้เกี่ยวกับรัฐศาสตร์และวัฒนธรรม\n                    ในชั้นเรียน ฉันเคยเรียน TOEIC เป็นเวลา 2 เดือนครึ่งและคะแนนของฉันก็พัฒนาแล้ว\n                    แต่จุดอ่อนของฉันยังคงเป็นการอ่าน\n                    ดังนั้นฉันจึงพยายามอ่านหนังสือให้มากที่สุดเท่าที่จะทำได้\n                    ฉันมักจะไปที่คาเฟ่ใกล้บ้านของฉันและพูดคุยกับเพื่อนบ้านและคนทำกาแฟ\n                    และฉันสนุกกับเวลาของฉันที่นั่น การพูดกับคนแปลกหน้าในสถานที่สาธารณะ\n                    ฉันรู้ว่าเรื่องนี้จะไม่เกิดขึ้นในญี่ปุ่น ถูกไหม?\n                    \n                    คุณได้รับอะไรอีกนอกจากภาษาอังกฤษ?\n                    การมีเพื่อนทั่วโลกมีความสำคัญต่อฉัน ฉันไม่เคยคิดเลยว่าฉันจะมีเพื่อนต่างชาติได้\n                    ฉันสัญญากับเพื่อนต่างชาติของฉันว่า เมื่อฉันเป็นพนักงานต้อนรับบนเครื่องบิน\n                    ฉันจะไปเยี่ยมเมื่อฉันบินไปประเทศของพวกเขา\n                    ฉันต้องการจะขอฝึกงานในภายหลังเพื่อที่ฉันจะได้เรียนรู้ภาษาอังกฤษในทางปฏิบัติที่\n                    ใช้ในที่ทำงานจริงๆ\n                    หลังจากนั้นฉันจะกลับไปญี่ปุ่นและสมัครบริษัทสายการบินอีกครั้ง\n                    เมื่อเทียบกับปีที่ผ่านมาฉันได้พัฒนาภาษาอังกฤษและประสบการณ์ในต่างประเทศและ\n                    แน่นอนว่าจะมีผลดีต่อการนำไปใช้กับบริษัทต่างชาติ\n                    ดังนั้นฉันจะสนุกกับชีวิตของฉันใน LA ทุกๆวัน\n                    \n                    คุณอยากจะแนะนำ MLI ให้กับนักเรียนที่กำลังจะมาหรือไม่?\n                    \n                    ฉันอยากจะแนะนำ MLI กับผู้ที่ต้องการสัมผัสกับสิ่งใหม่ๆ ช่วงอายุระหว่าง 20 ถึง 30 ปี\n                    หลายๆคนรู้สึกสบายใจเมื่ออยู่ที่นี่ มีกิจกรรมจัดขึ้นทุกวันศุกร์\n                    เพื่อให้ทุกคนสามารถเที่ยวชมสถานที่ต่างๆได้อย่างสนุกสนานโดยไม่ต้องพูดภาษาอัง\n                    กฤษได้อย่างคล่องแคล่ว ฉันเข้าใจว่าทุกคนมีเหตุผลที่แตกต่างกันในการมาที่ LA และ\n                    Westwood ตั้งอยู่ในพื้นที่ที่สมบูรณ์แบบ\n                    ดังนั้นจึงเป็นไปได้ที่คุณจะได้ศึกษาและเยี่ยมชมสถานที่ที่มีชื่อเสียงในเวลาเดียวกัน\n                    แน่นอนว่าฉันจะแนะนำคนอื่นๆที่คิดว่าการศึกษาเป็นสิ่งสำคัญที่สุด\n                    เพราะคุณสามารถเลือกหลักสูตรที่เหมาะสมจากชั้นเรียนและตัวเลือกต่างๆ\n                    นอกจากนี้ยังมีห้องสมุด คาเฟ่และ UCLA ใกล้ MLI\n                    เพื่อให้ง่ายต่อการเชื่อมต่อกับนักเรียนคนอื่นๆ แต่คุณก็รู้\n                    ทุกอย่างก็ขึ้นอยู่กับการสร้างความเปลี่ยนแปลงของคุณ\n                    \n                    ความคิดเห็นอื่นๆสำหรับ MLI?\n                    ไม่มีอะไรมาก ถ้าฉันต้องพูดอะไรบางอย่าง ... ฉันหวังว่าฉันจะมีโต๊ะขนาดใหญ่\n                    แต่นั่นแหล่ะ เจ้าหน้าที่ชาวญี่ปุ่นใจดีมาก พวกเขาสนับสนุนนักเรียนตลอดเวลา\n                    ดังนั้นคุณจึงไม่ต้องกังวลกับการใช้ชีวิตในอเมริกาเพียงคนเดียว นักเรียนมักจะมาที่\n                    LA ในช่วงวันหยุดฤดูใบไม้ผลิหรือฤดูร้อน\n                    ดังนั้นอาจมีนักเรียนญี่ปุ่นจำนวนมากในช่วงเวลาเหล่านั้นและคุณอาจได้ยินเสียงญี่ปุ่\n                    นที่โรงเรียนด้วยเช่นกัน แม้ว่า MLI\n                    มีข้อบังคับอย่างเข้มงวดเฉพาะภาษาอังกฤษสำหรับนักเรียน\n                    แต่ก็ยังคงเป็นปัญหาในการเรียนภาษาอังกฤษ\n                    \n                    มีเคล็ดลับอะไรสำหรับนักเรียนที่อยากมาเรียนต่อต่างประเทศบ้างไหม?\n                    \n                    ทุกคนมีเรื่องราวที่แตกต่างกันเมื่อเดินทางมาอเมริกา\n                    อย่างไรก็ตามนักเรียนจำนวนมากไม่สามารถใช้ความรู้ในต่างประเทศกับอาชีพของต\n                    นเองได้ แต่การจบการศึกษาในต่างประเทศของคุณเป็นความทรงจำที่ดี\n                    แต่มันทำให้ประสบการณ์ของคุณคุ้มค่ามากขึ้นหากคุณตั้งเป้าหมายที่ชัดเจนในขณะ\n                    ที่อยู่ใน LA ก่อนที่จะมา LA คะแนน TOEIC ของฉันอยู่ที่ประมาณ 600\n                    และเสียใจที่ไม่ได้ศึกษาและทบทวนล่วงหน้า\n                    หากคุณต้องการพัฒนาภาษาอังกฤษให้เร็วขึ้น\n                    ขอแนะนำให้คุณเรียนรู้คำศัพท์และเริ่มต้นตั้งแต่ตอนนี้\n                    ฉันหวังว่าคุณจะได้รับประสบการณ์ที่ยิ่งใหญ่ที่สุดใน LA!"},{id:36,image:"1628145767-Vanesa.jpg",campus_name:a,nationality_name:d,title:"Name: Vanesa",text:"ดาวเด่นสาขา Westwood\n\n                    ชื่อ : วาเนซ่า\n                    \n                    สัญชาติ : โบลีเวีย\n                    \n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ\n                    ฉันกำลังเรียนหลักสูตร ESL ค่ะ แล้วก็หลักสูตร CMAR ด้วย เพื่อช่วยในการออกเสียงของฉัน\n                    \n                    คุณเลือก MLI ได้อย่างไร\n                    \n                    ฉันอยากเรียนที่ Los Angeles เพราะ California สวยและอากาศดี ฉันค้นหาโรงเรียนต่างๆจากอินเทอร์เน็ต\n                    และคิดว่าที่ตั้งของ MLI ดีมากๆและราคาก็น่าสนใจ\n                    \n                    คุณคิดที่ไหนใน LA น่าไปที่สุด ?\n                    ฉันชอบไปทะเล ฉันรัก Malibu แล้วฉันก็ชอบพิพิธภัณฑ์ใน LA ด้วย โดยเฉพาะ LACMA\n                    เพราะที่นั่นมีสิ่งต่างๆมากมายให้ชม เช่น ศิลปะ เสื้อผ้า ของใช้ ภาพวาด และมันใหญ่มาก LA ใหญ่มาก\n                    และมีสถานที่ที่น่าไปมากมาย\n                    \n                    คุณคิดว่าคุณโตขึ้นไหม ตั้งแต่คุณมาอยู่ที่นี่?\n                    ฉันคิดว่าฉันได้เรียนรู้วัฒนธรรมใหม่ๆเสมอ ฉันกลายเป็นคนที่แข็งแกร่ง\n                    ฉันสามารถบอกได้ว่าภาษาอังกฤษของฉันดีขึ้นมากๆ ฉันพูดภาษาอังกฤษมากขึ้น\n                    แล้วก็เข้าใจมากขึ้นเวลาที่ฟังคนอื่นๆ ตอนแรกที่มาถึง ฉันคิดว่าภาษาของฉันแย่มากๆ\n                    ฉันไม่สามารถพูดได้เลย แต่ตอนนี้ฉันดีขึ้นมาก ฉันเรียนรู้มากขึ้นในทุกๆวัน\n                    \n                    ปกติคุณชอบทำอะไร?\n                    ฉันไปโรงเรียนจันทร์ – ศุกร์ ในตอนเช้า แล้วก็ไปยิมหลังเลิกเรียน\n                    ปกติฉันชอบค้นหาสถานที่ใหม่ๆทุกสัปดาห์ LA ใหญ่มากๆ และมีสิ่งใหม่ๆให้เห็นเสมอ\n                    ฉันชอบปั่นจักรยานเหมือนกัน ฉันอาศัยใน Santa Monica ที่นี่เป็นที่ที่สวยและน่าอยู่มากๆ\n                    และมีกิจกรรมมากมายให้ทำ\n                    \n                    คุณมีคำแนะนำอะไรไหมสำหรับคนที่กำลังตัดสินใจมา LA?\n                    สำหรับนักเรียนของ MLI คุณควรมาโรงเรียนทุกวัน เพราะเราจะได้เรียนรู้สิ่งใหม่ๆทุกวัน\n                    สำหรับอากาศที่นี่ดีมากๆ คุณสามารถใช้เวลาผ่อนคลายแบบสบายๆ ผู้คนใน LA ก็เป็นกันเองมากๆ\n                    สนุกสุดๆไปเลย"},{id:33,image:"1628144657-Esther.jpg",campus_name:a,nationality_name:g,title:"Name: Esther",text:"ดาวเด่นสาขา Westwood\n\n                    ชื่อ : เอสเธอร์\n                    \n                    สัญชาติ : เกาหลี (โตในญี่ปุ่น)\n                    \n                    คุณรู้จัก MLI ได้อย่างไร?\n                    อย่างแรกเลย ฉันค้นหาในอินเทอร์เน็ต ฉันเห็นโรงเรียนต่างๆมากมายใน Los\n                    Angeles โดยเฉพาะใน Koreatown ฉันพบว่าโรงเรียนใน Koreatown\n                    มีราคาถูกมาก แต่ฉันได้ยินมาว่าโรงเรียนเหล่านั้นไม่ค่อยดี\n                    ดังนั้นฉันเลยตัดสินใจไม่ไปเรียนที่นั่น ฉันค้นหาอีกครั้งและฉันก็พบ MLI\n                    ฉันอ่านความเห็นต่างๆเกี่ยวกับที่นี่ และฉันเห็นว่าส่วนใหญ่เป็นคนญี่ปุ่น\n                    ฉันชอบที่นี่เพราะทำให้ฉันรู้สึกสบายใจ ทุกอย่างที่เห็นเกี่ยวกับโรงเรียนนี้ก็ดีมากๆ\n                    และฉันก็ได้ยินว่า Westwood เป็นที่ที่ดีมาก ดังนั้นฉันจึงเลือก MLI\n                    และฉันก็รู้สึกพึงพอใจมากกับการตัดสินใจของฉันเอง\n                    \n                    สิ่งที่ดีที่สุดเกี่ยวกับ MLI คืออะไร?\n                    ฉันคิดว่าครูและเจ้าหน้าที่ใจดีและตลกมาก พวกเขามีความแตกต่างทางสัญชาติ\n                    ดังนั้นฉันจึงได้เรียนรู้วัฒนธรรมที่หลากหลายจากพวกเขา ซึ่งทำให้ฉันสนใจมากๆ\n                    ฉันสามารถเปรียบเทียบสิ่งต่างๆจากพวกเขา และคิดอะไรเพิ่มเติมเกี่ยวกับชาติต่างๆ\n                    \n                    คุณมักจะทำอะไรเมื่อมีเวลาว่าง ?\n                    ฉันกำลังอาสาช่วย Lindsay ผู้ดูแลเกี่ยวกับหลักสูตรที่โรงเรียน\n                    ฉันช่วยเธอจัดการเกี่ยบกับเอกสารต่างๆ ฉันอาสาทำงาน\n                    ดังนั้นฉันสามารถพัฒนาทักษะการสนทนาและฝึกปฏิบัติการใช้ภาษาอังกฤษ\n                    และมันมีประโยชน์มากจริงๆ แต่ถ้าเวลาว่างที่ฉันไม่ได้อยู่ที่โรงเรียน\n                    ฉันชอบผ่อนคลายอยู่ที่บ้านและออกไปข้างนอกกับเพื่อนเพื่อไปทานอาหารที่สถานที่ใ\n                    หม่ๆ รวมถึงสถานที่ท่องเที่ยวใหม่ๆอีกด้วย\n                    \n                    คุณชอบอะไรเกี่ยวกับ Los Angeles?\n                    อากาศที่นี่ดีมากๆ ฉันชอบผู้คนที่นี่ เพราะพวกเขาเป็นมิตร ถ้าฉันทักทาย “สวัสดี”\n                    หรือชวนคุย พวกเขาจะทักทายตอบอย่างเป็นมิตรและพูดประมาณว่า\n                    “ขอให้คุณมีวันที่ดี” ฉันชอบแบบนี้มากๆ\n                    \n                    คุณมีเคล็ดลับหรือคำแนะนำสำหรับนักเรียนที่กำลังคิดว่าย้ายว่าจะมา LA\n                    เพื่อมาเรียนที่ MLI ไหม?\n                    ถ้าคุณต้องการพัฒนาภาษาอังกฤษของคุณได้อย่างรวดเร็ว\n                    คุณต้องแน่ใจก่อนว่าคุณได้เรียนมามากพอโดยเฉพาะคำศัพท์ต่างๆ\n                    แค่การรู้ไวยากรณ์ไม่เพียงพอที่จะพูดภาษาอังกฤษได้\n                    คำศัพท์นั้นเป็นส่วนที่ยากที่สุดที่จะสามารถใช้เมื่อพูดได้\n                    \n                    นอกจากนี้ฉันได้ยินว่ามันอาจจะยากที่จะอยู่ใน LA โดยไม่มีรถ แต่ฉันไม่มีรถเลย\n                    รถเมล์และรถไฟฟ้าใต้ดินที่นี่ค่อนข้างดี ดังนั้นจึงไม่ใช่ปัญหาสำหรับฉัน"},{id:32,image:"1628142750-Sandrine.jpg",campus_name:b,nationality_name:n,title:"Name: Sandrine",text:"ดาวเด่นสาขา Hollywood\n                    ชื่อ : แซนดรีน โบทัน\n                    สัญชาติ : ฝรั่งเศส\n                    \n                    คุณกำลังเรียนหลักสูตรไหนอยู่คะ?\n                    ภาษาอังกฤษทั่วไป (ขั้นสูง)\n                    \n                    คุณมีอะไรอยากบอกกับนักเรียนใหม่ไหม:\n                    MLI เป็นโรงเรียนที่ดี ที่นี่มีครูที่ดีมากๆ\n                    เราสามารถเรียนรู้ได้อย่างรวดเร็วและเราเรียนรู้สิ่งต่างๆมากมาย เช่น\n                    การออกเสียง, ไวยากรณ์, วิธีการเขียนเรียงความ\n                    และวิธีการพูดคุยกับคนอื่นๆ นอกโรงเรียนในชีวิตจริง\n                    \n                    เราเรียนรู้วิธีการเขียน emails, เอกสารต่างๆ\n                    และการเขียนประวัติส่วนตัวเพื่อสมัครงาน\n                    \n                    มีอะไรที่นักเรียนควรรู้เกี่ยวกับชีวิตใน LA?\n                    ชีวิตใน LA น่าตื่นเต้นมากๆ ที่นี่มีสิ่งต่างๆมากมายให้ทำและค้นหา\n                    อากาศที่นี่ก็ดีมากๆ ผู้คนน่ารัก ฉันรู้จักโรงเรียนสอนเต้นที่ดีแห่งหนึ่ง ชื่อ\n                    Millenium (ในเมือง North Hollywood) และ ZH (ใกล้กับหอพักนักเรียน\n                    Melrose) 2 ที่นี้เป็นที่ที่ฉันชอบมากๆ\n                    \n                    ที่ไหนเป็นที่ที่ดีสำหรับการอยู่อาศัย?\n                    ฉันชอบ Valley Village เพราะว่ามันถูกและดี แต่ถ้าคุณอยู่ที่นี่\n                    คุณต้องมีรถเพื่อที่จะช่วยให้คุณได้ไปเที่ยวรอบๆเมือง\n                    \n                    ข้อแนะนำ:\n                    \n                    มาที่นี่ด้วยกระเป๋าที่ว่างเปล่า ที่นี่มีร้านค้าสำหรับช็อปปิ้งมากมาย\n                    Six Flags เป็นสวนสนุกที่เจ๋งมากๆ ถ้าหากคุณชอบเครื่องเล่น roller\n                    coasters และความท้าทาย"},{id:31,image:"1628140951-Momoka.jpg",campus_name:a,nationality_name:c,title:"Name: Momoka",text:"ดาวเด่นสาขา Westwood\n                    ชื่อ : โมโมกะ\n                    Nationality: Japanese\n                    สัญชาติ : ญี่ปุ่น\n                    \n                    คุณคิดอย่างไรกับ LA และ MLI?\n                    \n                    ที่นี่มีสิ่งทันสมัยต่างๆมากมาย เช่น ร้านค้าและผู้คน ที่นี่ยังมีความหลากหลายมากมายซึ่งน่าสนใจมาก\n                    รวมไปถึงนักเรียนชาวต่างชาติที่สามารถพูดภาษาอังกฤษได้ดีในชั้นเรียน\n                    บริเวณโรงเรียนสะอาดและใหญ่มาก มันดีจริงๆ\n                    \n                    คุณชอบทำอะไรเพื่อความสนุก?\n                    ฉันชอบอาสาสมัครเพื่อช่วยงาน MLI\n                    และฉันก็เป็นอาสาสมัครดูแลที่พักอาศัยสัตว์ในวันหยุดสุดสัปดาห์ที่กำลังจะเริ่มต้นในสัปดาห์หน้า\n                    ฉันไม่ได้มาที่นี่นานมากแล้ว แต่ฉันหวังว่าจะได้เที่ยวชมทุกที่ที่อยากไป โอ้! ฉันชอบช้อปปิ้งที่นี่ด้วย ฮ่าฮ่า!\n                    ฉันรัก Trader Joe's! ที่นั่นมีความสนุกสนานและสิ่งของราคาถูกมากมาย\n                    \n                    ตอนนี้คุณอาศัยอยู่ที่ไหน? คุณพอจะให้คำแนะนำกับนักเรียนใหม่ได้ไหม?\n                    ตอนนี้ฉันอยู่กับหอพักของโรงเรียน อยู่ใน Westwood ซึ่งใกล้กับโรงเรียนมากๆ\n                    ฉันขอแนะนำเพราะที่นี่อยู่ใกล้โรงเรียนมากๆ และระบบรถโดยสารประจำทางของ LA มักจะไม่ค่อยตรงเวลา\n                    UCLA ก็ใกล้มากๆ ดังนั้นแถวนี้จึงเต็มไปด้วยนักเรียนอยู่เสมอและฉันรู้สึกว่าได้รับอิทธิพลจากพวกเขา\n                    \n                    มีเคล็ดลับอะไรสำหรับนักเรียนใหม่ไหม?\n                    ฉันหวังว่าฉันจะรู้คำศัพท์มากกว่านี้ก่อนที่จะมา ซึ่งทำให้ฉันสามารถพูดได้มากขึ้นที่นี่\n                    มันเป็นเรื่องสำคัญที่ต้องพูดเยอะๆ ดังนั้นอย่ารู้สึกอายเมื่อคุณต้องพูด! LA มีร้านค้ามากมากให้ช็อปปิ้ง\n                    ดังนั้นคุณจึงไม่จำเป็นต้องนำสิ่งของต่างๆมามาก คุณแค่เอาเป้าหมายมา!\n                    เป้าหมายของฉันคือการจบการศึกษาจากมหาวิทยาลัยในสหรัฐฯ ถ้าคุณไม่มีเป้าหมายที่นี่\n                    คุณอาจไม่มีแรงจูงใจที่จะเรียนรู้ภาษาอังกฤษ แต่เป้าหมายจะผลักดันคุณ"},{id:30,image:"1628139214-Miharu.jpg",campus_name:b,nationality_name:c,title:"Name: Miharu",text:"ดาวเด่นสาขา Hollywood\n                    ชื่อ : มิฮารุ ฟูจิตะ\n                    สัญชาติ : ญี่ปุ่น\n                    \n                    คุณกำลังเรียนหลักสูตรใดอยู่คะ?\n                    ภาษาอังกฤษทั่วไป ระดับปานกลางขั้นสูง 2\n                    \n                    ทำไมคุณถึงเลือกหลักสูตร ESL?\n                    ฉันเลือกหลักสูตร ESL เพราะทักษะภาษาอังกฤษของฉันไม่ดีเลยตั้งแต่เริ่มต้น ในญี่ปุ่น\n                    ฉันเรียนภาษาอังกฤษแค่ในโรงเรียนมัธยมเท่านั้น ฉันไม่สามารถพูดได้เลย ดังนั้นหลักสูตร ESL\n                    จึงเป็นหลักสูตรที่ดีที่สุดสำหรับฉันที่จะพัฒนาการพูด การฟังและไวยากรณ์ของฉัน\n                    ฉันสามารถเรียนรู้ทุกอย่างในชั้นเรียน\n                    \n                    ทำไมคุณถึงมา LA?\n                    ฉันเป็นช่างทำผมและแต่งหน้าในญี่ปุ่น ฉันตัดสินใจมา LA เพราะฉันอยากถ่ายภาพใน LA\n                    \n                    คุณชอบอะไรเกี่ยวกับการอาศัยอยู่ใน LA?.\n                    อากาศ และที่นี่มีสถานที่ท่องเที่ยวต่างๆมากมาย เช่น ชายหาด ภูเขา พิพิธภัณฑ์และอื่นๆอีก\n                    \n                    อะไรเป็นสิ่งที่ยากที่สุดเกี่ยวกับการอาศัยอยู่ใน LA?.\n                    ฉันไม่มีรถ ดังนั้นมันจึงยากที่จะไปที่ต่างๆ\n                    \n                    คุณจะแนะนำอะไรให้กับนักเรียนใหม่ที่กำลังจะมา?.\n                    LA มีโอกาสมากมายสำหรับผู้ที่อยากทำงานในวงการบันเทิง ดังนั้นถ้าคุณต้องการทำงานในวงการ ควรมา\n                    LA! พยายามมีส่วนร่วมกับชาวอเมริกัน"},{id:29,image:"1628134935-Kaisei.jpg",campus_name:b,nationality_name:c,title:"ชื่อ : ไคเซะ ยามาดะ",text:"สัญชาติ : ญี่ปุ่น\n\n                    คุณกำลังเรียนหลักสูตรใดอยู่?\n                    ภาษาอังกฤษทั่วไป (ขั้นสูง)\n                    \n                    คุณคิดว่านักเรียนใหม่ควรรู้อะไรบ้างก่อนมา LA?\n                    เมื่อคุณมา LA คุณควรไปทุกที่ที่คุณอยากไป เช่น สถานที่ที่มีชื่อเสียง สถานที่ที่ผมชอบไปมากที่สุดคือทะเล ตัวเมือง LA และพิพิธภัณฑ์ต่างๆ\n                    \n                    คุณชอบทำอะไรใน LA?\n                    ผมชอบ LA เพราะที่นี่มีความหลากหลาย มีวัฒนธรรมต่างๆ แถวบ้านของผมในเมืองเกาหลี มีผู้อพยพจำนวนมาก ผมได้ยินภาษาต่างๆตามท้องถนน เช่น ภาษาสเปน ภาษาเกาหลี ฯลฯ\n                    \n                    คุณชอบอะไรเกี่ยวกับ MLI?\n                    อย่างแรกเลย ผมชอบครูผู้สอน พวกเขาเป็นมิตรมากๆ และพวกเขาสอนดีจริงๆ ไบรอัน เป็นครูสอนไวยากรณ์ เขาเคยอาศัยอยู่ในประเทศฝรั่งเศส และอีกคนหนึ่ง เกเบรียล เธอมาจาก Hollywood แต่เธอเคยอยู่ที่ประเทศชิลี พวกเขาทั้งคู่มีประสบการณ์ที่น่าสนใจมากมาย และพวกเขาเข้าใจความยากของการเรียนภาษาของชาวต่างชาติ\n                    \n                    คุณมีคำแนะนำอะไรไหมสำหรับนักเรียนที่กำลังจะมาในอนาคต?\n                    คุณควรมีส่วนร่วมกับกิจกรรมของ MLI เมื่อผมมาที่นี่ครั้งแรกผมมีส่วนร่วมกับงานเลี้ยง Halloween ผมรู้สึกกังวลเล็กน้อยเพราะผมไม่รู้จักใครเลย แต่มันกลายเป็นโอกาสที่ดีที่ได้พูดภาษาอังกฤษกับเพื่อนร่วมห้องและได้ทำความรู้จักกับเพื่อคนอื่นๆ กิจกรรมของ MLI สามารถช่วยให้คุณมีสังคมได้"},{id:28,image:"1628134661-ella.jpg",campus_name:b,nationality_name:d,title:"ชื่อ : เอลล่า พาราเวียล",text:"สัญชาติ : เยอรมัน\n\n                    มีอะไรที่นักเรียนควรรู้บ้างก่อนมา MLI ?\n                    พวกเขาควรรู้ว่าครูผู้สอนน่ารัก พวกเขาตั้งใจให้ความรู้ที่คุณต้องการจริงๆ ไม่ใช่แค่นั้น คุณควรรู้ด้วยว่าการพูดเร็วเป็นอย่างไร เพราะที่นี่มีแต่คนเจ๋งๆ\n                    นักเรียนที่นี่ จะไม่ใช่แค่เรียนภาษาอังกฤษ แต่ยังได้เรียนรู้วัฒนธรรมที่แตกต่างกันจากเพื่อนชาวต่างชาติ\n                    \n                    มีอะไรที่นักเรียนควรรู้บ้างก่อนมา LA ?\n                    LA อบอุ่นเสมอ ผู้คนก็เป็นมิตรมากๆ ชาวยุโรปไม่ต้องกลัวเมื่อมีคนทัก ‘สวัสดี’ หรือ ’เป็นไงบ้าง’ หรือการได้รับบริการที่ดี เป็นเรื่องปกติของที่นี่\n                    \n                    อะไรคือสิ่งที่ดีที่สุดเกี่ยวกับ LA?\n                    อากาศ ผู้คน ความหลากหลายของธรรมชาติ ที่นี่มีทั้งทะเลและภูเขา"},{id:27,image:"1628134450-sara.jpg",campus_name:a,nationality_name:l,title:"ชื่อ : ซาร่า",text:"คุณมาจากไหน : สเปน\n\n                    คุณคิดอย่างไรกับ LA?\n                    LA เป็นที่ที่เจ๋งมากๆ คุณสามารถหาสิ่งต่างๆทำได้มากมายไม่ว่าคุณจะเรียนหรือทำอะไรก็ตาม LA มีทุกอย่างที่คุณต้องการและยังมีคนต่างชาติมากมายอีกด้วย เป็นเมืองที่มีความหลากหลายทางเชื้อชาติมากๆ\n                    \n                    คุณชอบอะไรบ้างเกี่ยวกับ MLI?\n                    ฉันชอบหลักสูตร มีหลักสูตรมากมายเช่น TOEFL, Business + TOEIC, Conversation, ESL program ซึ่งฉันกำลังเรียนอยู่ เจ้าหน้าที่และครูที่นี่โดยทั่วไปมีความสุขและสนุกสนานเป็นอย่างมาก ที่นี่มีสภาพแวดล้อมที่ดีเสมอ โรงเรียนมีกิจกรรมที่จัดเตรียมไว้เสมอซึ่งเหมาะสำหรับการพบปะผู้คนโดยเฉพาะอย่างยิ่งถ้าคุณขี้อายหรือถ้าคุณมาที่ LA คนเดียวอย่างที่ฉันทำ มันเป็นวิธีที่ง่ายและสนุกสนานในการพบปะผู้คนและสนุกสนาน\n                    \n                    คุณชอบไปที่ไหนในช่วงเวลาว่าง? คุณชอบทำกิจกรรมแบบไหน?\n                    ฉันชอบหลายๆที่ที่นี่ ฉันเป็นนักดนตรี ดังนั้นฉันชอบไปคอนเสิร์ตรวมทั้งพิพิธภัณฑ์ศิลปะและการจัดแสดงนิทรรศการ มีสถานที่มากมายเช่น Disney Concert Hall และพิพิธภัณฑ์ ซานตาโมนิกาและเวนิสสนุกสนานเวลาไปกับเพื่อน การเที่ยวชมย่านดาวน์ทาวน์ Arts District อันเยี่ยมยอดและ Melrose มีร้านขายของมือสองมากมาย สถานที่ทุกแห่งมีความเป็นตัวเองและสถานที่ต่างๆก็ต่างกันออกไป ฉันทำงานอยู่เสมอ ฉันไม่เคยหยุดทำสิ่งต่างๆและยุ่งอยู่ตลอดเวลา ฉันอยู่กับครอบครัว ฉันจึงได้เห็น LA กับพวกเขามากมาย ฉันไม่เคยเบื่อที่นี่ ฉันสามารถค้นพบสิ่งใหม่ๆ ได้แม้กระทั่งบนถนนที่คุณสามารถเห็นภาพวาดและกราฟฟิตีได้\n                    \n                    ตอนนี้คุณอาศัยอยู่ที่ไหน? คุณแนะนำให้นักเรียนใหม่หรือไม่?\n                    ตอนนี้ฉันอยู่ที่มาลิบู มันดีมากและเงียบสงบ แต่ค่อนข้างไกลจากเมือง ดังนั้นฉันจะไม่แนะนำให้นักเรียนที่ไม่มีรถ ฉันรักมันเพราะสีเขียวและสงบ\n                    \n                    คุณมีคำแนะนำสำหรับนักเรียนที่กำลังจะมาหรือไม่?\n                    ไม่ต้องอายเพราะปกตินักเรียนต่างชาติจะขี้อายในตอนแรก เพียงแค่เป็นตัวเองและพยายามอย่างดีที่สุดเพื่อให้บรรลุความฝันของคุณ"},{id:26,image:"1628134197-shoi.jpg",campus_name:b,nationality_name:c,title:"ชื่อ : โชอิ สึชิยะ",text:"สัญชาติ :\n                    ญี่ปุ่น\n                    \n                    คุณกำลังเรียนหลักสูตรไหนอยู่?\n                    ภาษาอังกฤษทั่วไป ระดับปานกลางขั้นสูง 1\n                    \n                    คุณชอบทำอะไรเพื่อความสนุก?\n                    ผมเป็นนักเต้น ผมมักจะเรียนเต้นหลังเลิกเรียนที่โรงเรียนสอนเต้น Millenium (โรงเรียนสอนเต้นที่มีชื่อเสียงใน Studio City)\n                    บางครั้งผมก็ไปซื้อของ ผมชอบ Urban Outfitters นอกจากนี้ยังสนุกกับการซื้อสินค้าที่ The Groveและ Melrose ด้วย\n                    \n                    นักเรียนควรรู้อะไรบ้างก่อนที่จะมา LA?\n                    ศึกษาศัพท์ก่อนที่คุณจะย้ายไปอเมริกา คำศัพท์มีความสำคัญมาก\n                    และถ้าคุณเป็นนักเต้น คุณควรค้นหาโรงเรียนสอนเต้นก่อนที่คุณจะมา\n                    \n                    ภาษาอังกฤษของคุณดีขึ้นหรือไม่?\n                    ครับ ตอนที่ผมมาที่นี่เมื่อปีที่แล้วผมพูดภาษาอังกฤษไม่ได้เลย ตอนนี้ผมสามารถพูดภาษาอังกฤษและฉันเข้าใจทุกอย่างมากขึ้น\n                    \n                    คุณชอบ MLI ไหม?\n                    ครับ ผมชอบ MLI ทุกคนเป็นกันเองมากๆ นอกจากนี้โรงเรียนยังอยู่ในสถานที่ที่ดีถ้าคุณเป็นนักเต้น เพราะระแวกนี้มีโรงเรียนสอนเต้นมากมาย"},{id:25,image:"1628133870-hinata.jpg",campus_name:a,nationality_name:c,title:"ชื่อ : ฮินาตะ",text:"สัญชาติ :\n                    ญี่ปุ่น\n                    \n                    หลักสูตร :\n                    IELTS\n                    \n                    คุณอยู่ที่ LA มานานแค่ไหนแล้ว? คุณคิดอย่างไรกับที่นี่?\n                    ฉันอยู่ที่นี่มานานกว่าหนึ่งปีแล้ว ฉันชอบที่นี่เพราะสภาพอากาศ ผู้คนและแฟชั่น\n                    \n                    คุณชอบไปที่ไหนใน LA?\n                    ฉันชอบไปทะเล นอกจากนี้ฉันยังชอบไป The Grove โรงภาพยนตร์และซื้อของต่างๆ\n                    \n                    คุณคิดว่าอะไรทำให้ MLI แตกต่างจากโรงเรียนสอนภาษาอื่น ๆ ?\n                    ทุกคนที่นี่ใจดี ทุกคนรู้จักฉัน แม้ว่าฉันจะพูดได้ไม่ดี พวกเขาเข้าใจและแก้ไขข้อผิดพลาดของฉันได้\n                    \n                    คุณอาศัยอยู่แถวไหน? คุณอยากแนะนำที่นี่ให้นักเรียนใหม่หรือไม่?\n                    ฉันขอแนะนำ Park La Brea ที่นี่มีทุกสิ่งที่คุณต้องการและฉันสามารถเดินไปได้ทุกที่\n                    \n                    คุณมีแผนสำหรับอนาคตอย่างไรหลังจากจบการศึกษาที่ MLI?\n                    ฉันอยากเข้าเรียนต่อที่ UCLA ตอนนี้ฉันเป็นผู้ซื้อแฟชั่น และฉันจะทำอย่างนั้นต่อไป ฉันอาจศึกษาด้านธุรกิจและการตลาดที่ UCLA\n                    \n                    มีเคล็ดลับอะไรไหมสำหรับนักเรียนที่กำลังจะมาในอนาคต?\n                    คุณควรมา LA เพื่อการศึกษา!"},{id:24,image:"1628133568-touda.jpg",campus_name:a,nationality_name:d,title:"โรงเรียนสอนภาษาที่ถูกที่สุดใน Los Angeles!",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Touda จากประเทศโมร็อกโก ปัจจุบันเธอกำลังศึกษาอยู่ในหลักสูตรการสนทนาขั้นสูงของเราในช่วงบ่าย ในโมร็อกโกเธอเป็นนักข่าวและเรียนหลักสูตรสื่อสารมวลชนเพิ่มเติมใน Los Angeles เธอชอบเดินเขา ไปชายหาดและเยี่ยมชม Universal Studios นี่คือสิ่งที่เธอพูดเกี่ยวกับ MLI:\n                    \n                    ฉันเริ่มเรียนภาษาอังกฤษใน Los Angeles ที่ UCLA ตอนที่ฉันเรียนอยู่ที่นั่น ฉันได้ยินจากเพื่อนร่วมชั้น เกี่ยวกับ MLI เธอแนะนำโรงเรียนนี้ให้ ดังนั้นฉันจึงมาดูและตัดสินใจเรียนภาษาอังกฤษที่นี่ ที่นี่เป็นโรงเรียนที่ดีมากๆและเป็นโรงเรียน ESL ที่ถูกที่สุดใน Los Angeles ค่าเรียนของ UCLA ราคา $ 6,500 ต่อเทอมซึ่งแค่ 3 เดือนเท่านั้น ราคาแพงมาก แม่ของฉันพูดติดตลกว่าฉันต้องเป็นเจ้าหญิงโมร็อกโกเพราะค่าเรียนของฉันมีราคาแพงมาก [3 เดือนที่ MLI แค่ $ 1,200 สำหรับหลักสูตรสนทนาตอนบ่าย] ทั้ง 2 โรงเรียนใกล้กันมากใน Westwood ซึ่งเป็นย่านที่ฉันอาศัยอยู่ ฉันรักละแวกนี้เนื่องจากเป็นศูนย์กลางของนักเรียนและมหาวิทยาลัยนานาชาติและมีนักศึกษาจำนวนมาก ตอนนี้ฉันกำลังเรียนหลักสูตรการสนทนาซึ่งช่วยให้ฉันสามารถพัฒนาทักษะการพูดในชีวิตประจำวัน ถ้าคุณต้องการพัฒนาทักษะการพูดของคุณ นี่คือชั้นเรียนที่ดีที่สุดที่จะเรียน ฉันคิดว่าถ้านักเรียนต้องการเรียนภาษาอังกฤษ พวกเขาควรจะมาเรียนที่สถาบัน MLI เพราะอยู่ใกล้ UCLA และเป็นโรงเรียนสอนภาษาอังกฤษที่ถูกที่สุด! ฉันรักโรงเรียนนี้จริงๆ"},{id:23,image:"1628132640-denis.jpg",campus_name:a,nationality_name:h,title:"โรงเรียนสอนภาษาที่ดีที่สุดใน Los Angeles",text:"ดาวเด่นจากสาขา Westwood ในสัปดาห์นี้คือ Denis จากรัสเซีย เขาชอบการใช้ชีวิตใน LA เพราะมีกิจกรรมกลางแจ้งมากมาย เขารักการปั่นจักรยานเสือภูเขาและเคยเป็นนักขี่จักรยานมืออาชีพ ที่ LA เขาขี่จักรยานเป็นงานอดิเรกและชอบขี่จักรยานจาก Mulholland Drive ไปทะเล (ซึ่งโดยปกติจะใช้เวลาขับรถหนึ่งชั่วโมง แต่เขาสามารถขี่จักรยานได้ภายใน 15 นาที!) นอกจากนี้เขายังชอบเล่นสกีที่ Big Bear และ Mammoth Mountain รวมถึงการเล่นเซิร์ฟที่ Huntington Beach ด้วย ปัจจุบันเขากำลังเรียนหลักสูตรเตรียมตัวสอบ TOEFL\n\n                    ตอนแรกผมคิดว่า LA น่าเบื่อและสกปรก เพราะผมอยู่ใกล้ LAX แล้วผมก็เริ่มออกและย้ายไปที่ Santa Monica และผมคิดว่าผมผิด LA เป็นเมืองใหญ่ที่มีเมืองเล็กๆอยู่มากมาย จริงๆแล้วผมใช้เวลาประมาณ 2 สัปดาห์ในการค้นหาโรงเรียน ESL ต่างๆใน Los Angeles เช่น โรงเรียนสอนภาษาอื่นๆใน Korea town ผมใช้เวลา 2-3 วันในแต่ละโรงเรียนเพื่อทดลองเรียน TOEFL แฟนของผมและผมต้องการสถานที่ที่จะให้ความรู้ใหม่ๆมากมายแก่เรา มีเหตุผลบางอย่างที่ทำให้เราตัดสินใจว่า MLI เป็นโรงเรียน ESL ที่ดีที่สุดสำหรับเราและเลือกเรียนที่นี่ ก่อนอื่นโรงเรียนนี้ค่อนข้างใหม่ มีสิ่งอำนวยความสะดวกที่ใหม่และทันสมัย ที่นี่มีความสะดวกสบายในการเรียนโดยเฉพาะเมื่อเทียบกับโรงเรียนในเขต Korea town ประการที่สองคือผมชอบบทเรียนที่ผมได้ลอง รูปแบบของบทเรียนในชั้นเรียน TOEFL ดีมาก คล้ายกับที่รัสเซีย ประการที่สามราคาดีกว่าโรงเรียน ESL อื่นๆ ก่อนที่จะเลือก MLI ผมเคยได้ยินว่า Kaplan เป็นโรงเรียนที่ดีที่สุดใน Los Angeles แต่มันเป็นราคาที่เท่าตัวของ MLI และเมื่อผมได้ลองเรียน TOEFL คุณภาพไม่ดีกว่า คำแนะนำสำหรับนักเรียนใหม่ คือ ถ้าคุณต้องการประสบความสำเร็จจริงๆ คุณต้องเลือกชั้นเรียนที่คนอื่นต้องการเรียนและต้องการได้รับความรู้เร็วที่สุด บางโรงเรียนมีนักเรียนที่ต้องการแค่รักษาสถานะวีซ่าและไม่อยากเรียน แต่ที่ MLI ไม่ใช่ปัญหาเลย นักเรียนที่นี่ดูอยากเรียนรู้ทุกคน"},{id:22,image:"1628132309-bruno.jpg",campus_name:b,nationality_name:f,title:"ชีวิตในแคลิฟอร์เนีย",text:"นักเรียนที่โดดเด่นในสัปดาห์นี้คือบรูโน่จากบราซิล บรูโน่ทำงานด้านพลศึกษา การวิ่งออกกำลังกายและฝึกออกกำลังกายในบราซิล มาดูสิ่งที่เขาพูดถึงชีวิตในแคลิฟอร์เนีย\n\n                    ผมรัก Los Angeles เพราะที่นี่เหมือน Rio de Janeiro แต่ใหญ่กว่าและอันตรายน้อยกว่า Los Angeles เป็นเมืองใหญ่ที่มีผู้คนจากทั่วโลก มีอากาศอบอุ่น แจ่มใสและบรรยากาศที่ดี ที่ Los Angeles คุณสามารถสร้างวิถีชีวิตที่คุณต้องการได้ ในช่วงเวลาว่างผมชอบออกกำลังกายที่ยิม Gold ไปร้านอาหารกับเพื่อน ไปชายหาดและเดินขึ้นเขา ทุกคนควรไป Staples Center ในย่านใจกลางตัวเมือง L.A เนื่องจากทีมที่ดีที่สุดใน NBA ชื่อ Lakers เล่นอยู่ที่นั่น Dodger เป็นสนามเบสบอลที่เจ๋งมากเช่นกัน กลุ่มคนชอบเบสบอลเหมือนกลุ่มคนชอบฟุตบอลในบราซิล ผมอยากแนะนำบาร์ \"บังกะโล\" ในซานตาโมนิกาเพราะอยู่กลางแจ้งข้างชายหาดและมีสาวสวยๆชอบไปงานเลี้ยงที่นั่น บาร์ที่ผมชอบไปใน West Hollywood คือ Barney's บนถนน Santa Monica ที่นั่นมีโต๊ะพูล ดนตรีและคาราโอเกะ\n                    \n                    ผมอาศัยอยู่ใน West Hollywood ที่นั่นปลอดภัย สงบ สะอาดและมีอะไรให้ทำมากมาย เช่น บาร์ ร้านอาหาร ฯลฯ ผมเคยอยู่ที่ Beverly Hills และผมชอบที่นั่นเหมือนกัน มีแหล่งช้อปปิ้งที่มีชื่อเสียง เช่น The grove จำไว้ว่า Los Angeles มีขนาดใหญ่และระบบขนส่งสาธารณะไม่ดี ผมเลยขี่จักรยานไปโรงเรียน แต่คุณสามารถเช่าหรือซื้อรถได้ โดยทั่วไปชีวิตใน Los Angeles มีราคาแพง เมื่อเทียบกับสถานที่อื่นๆ ในประเทศสหรัฐอเมริกา แต่มันคุ้มค่า\n                    \n                    ผมอยากแนะนำ Los Angeles ให้กับทุกคน!"},{id:21,image:"1628128541-lisa.jpg",campus_name:a,nationality_name:d,title:"ทำอย่างไรให้ได้คะแนน TOEFL 100+!",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Lisa จากประเทศเยอรมนี เธอเพิ่งประสบความสำเร็จในการสอบ TOEFL เธอทำได้ 108 คะแนน ในช่วงเวลาว่างของเธอ เธอชอบถักนิตติ้ง เธอทำบล็อกในภาษาอังกฤษและยังชอบทำอาหารและลองอาหารใหม่ๆใน Los Angeles เธอแนะนำให้ทุกคนลองชิมอาหารต่างๆในขณะที่พวกเขากำลังเรียนอยู่ที่นี่ เพราะอาหารที่นี่มีความหลากหลายมากและมีอาหารสชาติต้นตำรับจำนวนมากที่นี่ สถานที่โปรดของเธอใน Los Angeles คือ Abbott Kenney ในเมืองเวนิส\n                    \n                    ฉันเรียนหลักสูตร TOEFL เป็นเวลา 12 สัปดาห์ ก่อนที่จะเรียน TOEFL ฉันเรียนในหลักสูตร ESL ที่ MLI ฉันได้ 108 คะแนน เพราะฉันฟังทุกอย่างที่ Kyle (ครูสอน TOEFL) พูด ชั้นเรียนของเขาดีมากสำหรับการพัฒนาคะแนนของคุณ หลังเลิกเรียนฉันมักจะทบทวนบทเรียนที่บ้านเพื่อดูว่าฉันพลาดอะไรไปและคิดว่าทำไมฉันถึงพลาด ฉันคิดว่าวัตถุประสงค์ วิธีการและการถามคำศัพท์ในการอ่านเป็นคำถามที่ยากที่สุดสำหรับฉัน ฉันคิดว่าคำศัพท์ในชั้นเรียนนั้นยากกว่าการทดสอบ ฉันคิดว่าสำหรับนักเรียนที่ต้องการพัฒนาทักษะภาษาอังกฤษของพวกเขาจริงๆ เพื่อให้สามารถสอบผ่าน TOEFL ได้พวกเขาจำเป็นต้องเปลี่ยนชีวิตส่วนตัวของพวกเขาให้เป็นภาษาอังกฤษจริงๆ ตัวอย่างเช่น คุณต้องดูภาพยนตร์เป็นภาษาอังกฤษ มีส่วนร่วมในการพูดคุยเป็นภาษาอังกฤษ โดยเฉพาะอย่างยิ่งต้องคิดเป็นภาษาอังกฤษ และฉันคิดว่า Kyle's Strategy Guide [หนังสือ TOEFL ที่เขียนโดยครูผู้สอนภาคเช้าและบ่าย] เป็นประโยชน์เช่นกัน โดยเฉพาะส่วนที่มีโครงสร้างคำพ้องความหมาย มันมีประโยชน์มากเพื่อให้ทราบว่าจะเปลี่ยนคำลงในคำพ้องความหมายได้อย่างไร นอกจากนี้การถามคำถามในการพูดก็มีประโยชน์มาก ฉันใช้คู่มือนี้เพื่อเตรียมตัวสอบ"},{id:20,image:"1628128170-adbulmajeed.jpg",campus_name:b,nationality_name:k,title:"การเข้าเรียนต่อที่วิทยาลัยใน Los Angeles",text:"เจย์มาจากเมืองเจดดาห์ ประเทศซาอุดิอารเบีย เขาสำเร็จการศึกษาระดับปริญญาตรีด้านการบริหารจัดการโรงแรมจากมหาวิทยาลัย Prince Sultan ในเจดดาห์ในปี 2556 ในเดือนพฤษภาคมปี 2559 เขาย้ายมา Los Angeles ด้วยความหวังว่าจะมาคว้าปริญญาโทด้านอาหารและการจัดเลี้ยงจากวิทยาลัยในสหรัฐอเมริกา ฉันได้พูดคุยกับเจย์ในสัปดาห์นี้เพื่อเรียนรู้เพิ่มเติมเกี่ยวกับเส้นทางสู่มหาวิทยาลัย\n\n                    ในปี 2559 ผมมาแคลิฟอร์เนียด้วยทุนการศึกษาจากรัฐบาล เพื่อพัฒนาทักษะภาษาอังกฤษและเข้าเรียนต่อระดับวิทยาลัย สำหรับนักศึกษาต่างชาติ วิทยาลัยในสหรัฐฯต้องการคะแนน TOEFL หรือ EILTS เพื่อแสดงระดับความสามารถทางภาษาอังกฤษให้กับมหาวิทยาลัย ผมไม่รู้เกี่ยวกับการสอบ TOEFL ก่อนที่จะมาอเมริกา นอกจากแค่แบบทดสอบภาษาอังกฤษ\n                    \n                    ก่อนที่ผมจะเข้าเรียนต่อระดับมหาวิทยาลัยได้ ผมต้องปรับปรุงทักษะการเขียน ผมตัดสินใจเลือกเรียนหลักสูตร ESL ที่ MLI หลังจากนั้นผมตัดสินใจเรียน TOEFL เพื่อเตรียมพร้อมสำหรับการทดสอบ ผมต้องทำคะแนนให้ได้ 80-90 คะแนน Northridge College ในรัฐแคลิฟอร์เนียต้องการ 84 คะแนนในการสอบ TOEFL และวิทยาลัย Pomona ใช้ 89 คะแนน\n                    \n                    ตอนนี้ผมเรียนหลักสูตร TOEFL มา 5 เดือนแล้ว มันท้าทาย เรามุ่งเน้นไปที่กลยุทธ์การทดสอบ คำศัพท์ด้านวิชาการ การอ่านและการเขียนเรียงความ เราต้องสรุปการอ่านและการบรรยายเชิงวิชาการ หลักสูตร TOEFL ช่วยพัฒนาทักษะภาษาอังกฤษของผมเป็นอย่างมาก\n                    ตอนนี้ผมสามารถสรุปและทำความเข้าใจแนวคิดหลักของการบรรยาย การอ่านและการฟังได้โดยไม่ต้องอ่านรายละเอียดทั้งหมด\n                    \n                    นอกจากการสอบ TOEFL แล้ว ผมต้องเข้ารับการทดสอบ GMAT เพื่อสมัครปริญญาโท ผมจะเรียนกับครูสอนพิเศษส่วนตัวเพื่อช่วยเตรียมตัวให้พร้อม เมื่อผมมีคะแนน TOEFL และ GMAT แล้ว ผมจะสมัครเรียนวิทยาลัย Northridge วิทยาลัย Pomona และมหาวิทยาลัย Tampa State ในฟลอริด้า\n                    \n                    สิ่งที่ผมจะแนะนำสำหรับคนที่อยากจะเรียนต่อวิทยาลัย คือ ต้องรู้ข้อกำหนดของวิทยาลัยสำหรับการสมัครก่อนที่จะย้ายมาอเมริกา นี่จะช่วยให้คุณเลือกหลักสูตรภาษาอังกฤษที่ดีที่สุดสำหรับคุณ"},{id:19,image:"1628127696-alejandra.jpg",campus_name:a,nationality_name:l,title:"ตารางเรียนทั่วไปของนักเรียน ESL",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Alejandra เธอมาจากมาดริด ประเทศสเปน เธอทำงานเกี่ยวกับภาพยนตร์และอุตสาหกรรมสื่อในสเปนและได้ทำงานในรายการใหญ่ เช่น \"The Voice : Spain\" ในช่วงเวลาว่างของเธอ เธอชอบเล่นวอลเลย์บอลและดูภาพยนตร์\n                    \n                    โดยปกติฉันไปโรงเรียนวันจันทร์ถึงศุกร์ 9.00-12: 50 น. [หลักสูตร ESL ขั้นกลาง 2] หลังจากเลิกเรียนฉันกลับไปที่อพาร์ตเมนต์ เตรียมตัวออกไปเที่ยวกับเพื่อนเพื่อทำความรู้จักและสำรวจเมืองลอสแอนเจลิส ฉันชอบไป Melrose Ave เพื่อไปซื้อของและไปที่ Santa Monica Beach เพื่อเล่นวอลเลย์บอลชายหาดกับเพื่อนที่อาศัยอยู่ที่ LA ฉันสนุกกับการไปดูหนังที่นี่ ซึ่งช่วยปรับปรุงทักษะการฟังของฉัน ในวันสุดสัปดาห์ ฉันชอบออกเดินทางนอกลอสแอนเจลิส ลอสแองเจลิสอยู่ใกล้กับสถานที่ต่างๆ เช่น วันหยุดสุดสัปดาห์ที่ฉันเดินทางไปแอริโซนากับเพื่อน เราไปที่ Monument Valley และ Antelope Canyon! ฉันสนุกมากและสถานที่เหล่านั้นน่าทึ่งจริงๆ ฉันอาศัยอยู่ในฮอลลีวู้ดซึ่งเจ๋งมากเพราะมีสตูดิโอมากมาย เช่น Netflix และ Paramount Pictures ดังนั้นจึงสนุกกับการได้อยู่กับสิ่งต่างๆเหล่านั้น ฉันคิดว่านักเรียนควรวางแผนที่จะมาเรียนที่ Los Angeles นานกว่า 3 เดือนเพื่อจะมีโอกาสได้รู้จักแคลิฟอร์เนีย ฉันไม่มีเวลาเพียงพอที่นี่เพื่อเห็นทุกอย่างที่ฉันอยากเห็น ฉันมีความสุขกับลอสแองเจลีส แต่ต้องการเวลามากขึ้นกว่าที่ฉันมี ฉันคิดว่า MLI เป็นโรงเรียนภาษา ESL ที่ดีเพราะมีนักเรียนเชื้อชาติต่างๆมากมายที่นี่ นอกจากนี้ครูมีความใกล้ชิดและดีมากๆ ฉันคิดว่ามันสนุกมากเพราะมีกิจกรรมมากมายอยู่เสมอ"},{id:18,image:"1628127256-haruka.jpg",campus_name:b,nationality_name:c,title:"ครูที่ดีที่สุดที่ฉันเคยเจอ",text:"ดาวเด่นสาขา Hollywood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Haruka Mishiro จาก Chiba ประเทศญี่ปุ่น เธอย้ายมา Los Angeles เมื่อ 10 เดือนก่อนเพื่อเรียนภาษาอังกฤษที่ MLI หลังจากเลิกเรียนเธอจะไปเรียนเต้นที่ Millenium and Edge เธอชอบ Jazz funk และเธอชอบการแสดง ฮารุกะได้คุยกับฉันวันนี้เกี่ยวกับชั้นเรียนของเธอที่ MLI และครูสอนภาษาอังกฤษที่เธอโปรดปราน\n                    \n                    \" ฉันเรียนที่ MLI มาเกือบปี ฉันเริ่มเรียนตั้งแต่ระดับเริ่มต้น 1 แต่ตอนนี้ฉันอยู่ในระดับปานกลาง 2 ครูที่ดีที่สุดที่ฉันเคยเจอ คือ Lisa เธอเป็นครูสอนวิชาไวยากรณ์ในระดับเริ่มต้น 1 และ 2 เธอสอนอย่างชัดเจนและช้าๆ เพื่อให้ทุกคนเข้าใจ เธออดทนมาก\n                    ฉันได้เรียนรู้อะไรมากมายจากเธอ เราฝึกกันพูดคุยกันทุกวันในชั้นเรียน เราจะพูดถึงสิ่งที่เราทำในช่วงสุดสัปดาห์ทุกวันจันทร์ มันมีประโยชน์เพราะเราได้พูดคุยและฝึกไวยากรณ์ในการสนทนา นอกจากนี้เรายังได้เรียนรู้เกี่ยวกับเพื่อนร่วมชั้นของเรา บางครั้งเราเล่นเกมทดสอบไวยากรณ์ในชั้นเรียน เช่น บิงโก จะแบ่งออกเป็น 2 ​​ทีมและเราจำเป็นต้องแต่งประโยค ตัวอย่างเช่น เราจะต้องสร้างประโยคโดยใช้ \"be verb\", \"going to\", \"will\" หรือ \"was\" ฉันชอบเกมเพราะสนุกและน่าตื่นเต้น เราทุกคนตะโกนและเชียร์ เพราะเราทุกคนต้องการที่จะชนะเกมและเป็นทีมที่ดีที่สุด ลิซ่าช่วยเราในการออกเสียงด้วยซึ่งฉันชอบ\n                    \n                    ลิซ่าเป็นคนใจดี ฉันรักเอเรียล ตัวละครดิสนีย์จากลิตเติลเมอร์เมด วันหนึ่ง Lisa ได้สอนชั้นเรียนของ Beginner เพลง \"Part of Your World\" ทั้งชั้นร้องเพลงด้วยกันและมันสนุกมาก หลังจากเลิกเรียน ฉันและเพื่อนร้องเพลงนั้นซ้ำๆ ลิซ่าเป็นครูที่ดีและเธอให้กอดที่ดีที่สุด กอดของเธอทำให้ฉันมีความสุขเสมอ! \""},{id:17,image:"1628126940-chintan.jpg",campus_name:b,nationality_name:d,title:"กิจกรรมของนักเรียน",text:"ดาวเด่นสาขา Hollywood\n\n                    Chintan Shah เกิดและเติบโตในเมืองมุมไบ ประเทศอินเดีย เขาศึกษาเทคโนโลยีสารสนเทศ ที่มหาวิทยาลัยและทำงานเป็นช่างเทคนิคด้านไอทีเป็นเวลาหนึ่งปี อย่างไรก็ตาม Chintan มีความฝันที่จะเป็นผู้อำนวยการสร้างภาพยนตร์ ดังนั้นเขาจึงลาออกจากงานในอินเดียและย้ายมา Los Angeles ในช่วงสี่ปีที่ผ่านมาเขาอาศัยอยู่ที่ L.A. ทำงานเกี่ยวกับหนังสั้นกว่า 20 เรื่องและมิวสิควิดีโอ 15 เพลง ปัจจุบันเขาถ่ายทำวิดีโอและงานเบื้องหลังให้กับสื่อสังคมออนไลน์ให้กับคนดังมากมาย\n                    \n                    ในช่วง 6 เดือนที่ผ่านมา Chintan เรียนหลักสูตร Business \u002F TOEIC ที่ MLI Hollywood เพื่อพัฒนาทักษะทางธุรกิจและการออกเสียง Chintan มักมีส่วนร่วมในกิจกรรมของโรงเรียน ดังนั้นฉันจึงได้พูดคุยกับเขาเกี่ยวกับประสบการณ์ที่น่าสนใจของเขา\n                    \n                    การร่วมกิจกรรมของโรงเรียนมันเจ๋งมาก เพราะผมได้พบกับผู้คนจำนวนมากที่แตกต่างทางเชื้อชาติ ช่วยให้เราเรียนรู้ทางวัฒนธรรมและรู้จักเพื่อนใหม่ ผมไปลาสเวกัสโดยมีนักเรียนกว่า 30 คน จากทั้ง Hollywood และ Westwood เราไปบาร์ คลับ และดื่มกันบนถนนของเวกัสกับเพื่อนๆ มันน่าตื่นตาตื่นใจ! และเป็นช่วงเวลาที่ดีที่สุด!\n                    \n                    ผมไปทัศนศึกษาด้วย เราเข้าชมพิพิธภัณฑ์ Broad, Last Bookstore และเรายังเห็นตลาด Grand Central ซึ่งเป็นหนึ่งในสถานที่ที่ดีที่สุดที่ผมเคยได้กิน เพื่อนของผมกินที่ไข่เจียวและพวกเขาก็ชอบมันมาก!\n                    \n                    ผมไป LACMA และพิพิธภัณฑ์ประวัติศาสตร์ธรรมชาติเช่นกัน เราเล่นเกมกันที่นั่น ซึ่งเราต้องหาที่จัดแสดงผลงานที่แตกต่างกันถึง 13 ชนิดและถ่ายเซลฟี่กับทีมเพื่อชัยชนะ ที่ LACMA ผมได้เห็นการสะสมงานศิลปะที่แตกต่างกัน มีศิลปินและวัฒนธรรมมากมาย\n                    \n                    ผมอยากแนะนำให้มีส่วนร่วมในกิจกรรมของโรงเรียน เพราะได้ทั้งความรู้และความสนุกสนาน"},{id:16,image:"1628125406-cindy.jpg",campus_name:a,nationality_name:f,title:"เรียน ESL ใน Los Angeles",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ ซินดี้ จากบราซิล เธอทำงานเป็นนักออกแบบตกแต่งภายในและวางแผนที่จะศึกษาสถาปัตยกรรมที่มหาวิทยาลัยในลอสแอนเจลิส ตอนนี้เธออาศัยอยู่ที่นี่มา 5 เดือนแล้วและเธอก็ชอบไปเที่ยวชายหาดและคลับมากๆ\n                    \n                    ฉันเรียนภาษาอังกฤษที่ Los Angeles มาประมาณ 5 เดือนแล้ว เมื่อฉันมาถึง MLI ครั้งแรกฉันรู้สึกประหลาดใจเพราะนักเรียนที่นี่จริงจังมาก ฉันเคยไปโรงเรียน ESL อื่น แต่ฉันคิดว่า MLI เป็นโรงเรียนที่ดีที่จะเรียนภาษาอังกฤษเพราะนักเรียนทุกคนจริงจังกับการเรียนภาษาอังกฤษ ฉันอาศัยอยู่ในเมืองคัลเวอร์ซิตีและฉันขอแนะนำให้กับนักเรียน โดยเฉพาะชาวบราซิลเนื่องจากมีชาวบราซิลจำนวนมากอาศัยอยู่ที่นั่น ดังนั้นจึงเป็นเรื่องสนุก ฉันคิดว่า Westwood [ที่ตั้งของวิทยาเขต] เป็นสถานที่ที่ดีในการอาศัยเช่นกันเพราะอยู่ใกล้กับโรงเรียนและเป็นสถานที่ที่ดี ใน LA มีอะไรมากมายให้ทำ ฉันชอบไปทะเล หาดเวนิสเป็นสถานที่โปรดของฉัน ฉันยังชอบไปคลับเพราะฉันรักการเต้น ตอนนี้ฉันมีเพื่อนต่างชาติมากมาย ดังนั้นฉันจึงชอบออกไปเที่ยวกับพวกเขา โดยปกติหลังจากเลิกเรียนฉันมักจะไปที่ชายหาด ไปยิม รับประทานอาหารเย็นกับเพื่อนๆ ฉันชอบสวนสนุกใน Los Angeles เช่น Universal Studios และ Six Flags มันเจ๋งมาก นอกจากนี้ยังมีอีกหลายที่ที่นักเรียนจะมีส่วนร่วมและพบปะผู้คน แน่นอน ฉันขอแนะนำให้นักเรียนคนอื่นๆ ที่เรียนอยู่ใน Los Angeles ว่า LA ไม่ใช่สถานที่ราคาถูก แต่ฉันคิดว่าที่นี่ดีกว่าบราซิล ฉันรักที่นี่มาก! ฉันมีรอยสักรูป Los Angeles เพราะฉันรู้สึกเหมือนฉันอยู่ที่นี่และหวังว่าฉันจะอยู่ที่นี่ตลอดไป ที่นี่เป็นสถานที่ที่สวยงามจริงๆ ให้ความรู้สึกที่ดีมากๆ คนน่ารักและเป็นมิตรในโรงเรียนและอากาศที่ดี ฉันขอแนะนำให้ทุกคนมาเรียนภาษาอังกฤษที่ Los Angeles"},{id:15,image:"1628124992-giovanna.jpg",campus_name:a,nationality_name:o,title:"เคล็ดลับสำหรับนักเรียนที่กำลังจะมา",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Giovanna จากอิตาลี Giovanna มาจากชนบทของอิตาลีที่อยู่ใกล้เมืองเวนิส เธอชอบวาดรูป ถ่ายรูปและเย็บผ้าในช่วงเวลาว่างของเธอ นอกจากนี้เธอยังสนุกไปกับการขับรถเที่ยวรอบๆ Los Angeles เพราะเธอเพิ่งได้รับใบอนุญาตขับขี่สัปดาห์ที่แล้ว ปัจจุบันเธอกำลังเรียนหลักสูตร TOEFL ช่วงเย็น\n                    \n                    ฉันคิดว่าสิ่งสำคัญคือนักเรียนต้องไม่พูดภาษาของพวกเขาขณะเรียนภาษาอังกฤษใน Los Angeles แม้ในขณะที่ฉันอยู่กับคนอิตาเลียนด้วยกัน ฉันมักจะพูดภาษาอังกฤษ โดยเฉพาะอย่างยิ่งเมื่ออยู่ต่อหน้าเจ้าของภาษาอังกฤษ ฉันคิดว่านักเรียนต้องพูดภาษาอังกฤษให้ได้มากเท่าที่จะเป็นไปได้ นอกจากนี้ฉันยังแปลและทำความเข้าใจกับเพลงทั้งหมดที่ฉันฟังและเลียนแบบการร้องเพลงของพวกเขาเพื่อใช้ในการออกเสียงและเริ่มต้นวันใหม่ของฉันด้วยการอ่านหนังสือพิมพ์ภาษาอังกฤษ ทั้งข่าวในสหรัฐและข่าวของประเทศฉันเอง ซึ่งเป็นประโยชน์มากๆสำหรับการเรียนรู้คำศัพท์และได้รู้ว่ามีอะไรเกิดขึ้นที่ไหนบ้าง ตอนนี้ฉันพักอยู่ใน Inglewood ค่าเช่ามีราคาถูกมาก แต่บางพื้นที่ค่อยข้างอันตราย ฉันอาศัยอยู่ระหว่างเจฟเฟอร์สันกับอดัมส์ และเพื่อนบ้านส่วนใหญ่เป็นเหมือนครอบครัวที่อยู่รอบๆ ดังนั้นจึงเป็นเรื่องที่ดีสำหรับฉัน นอกจากนี้ยังใกล้สถานีรถไฟใต้ดิน Farmdale ด้วย ดังนั้นจึงสามารถเดินทางไปรอบๆ Los Angeles ได้โดยง่าย ฉันคิดว่านักเรียนต้องตระหนักถึงสภาพแวดล้อมของพวกเขาอยู่เสมอและอย่าเพิ่งเชื่อใจทุกคนที่พวกเขาพบ ฉันชอบไปพิพิธภัณฑ์ศิลปะที่นี่ มีพิพิธภัณฑ์มากมายที่ไม่มีค่าใช้จ่าย เช่น The Broad ซึ่งน่าสนใจมาก ฉันชอบหอดูดาว Griffith ด้วย พวกเขาแสดงให้เห็นว่าดวงดาวเป็นสิ่งที่น่าอัศจรรย์จริงๆ ฉันคิดว่านักเรียนต้องหาสถานที่ของตนเอง ไม่ใช่แค่สิ่งที่พวกเขาเห็นบน Instagram เท่านั้น อันที่จริง LA ดีกว่าที่คุณเห็นในสื่อสังคมออนไลน์ ฉันสนุกกับการเรียนภาษาอังกฤษที่ MLI ฉันชอบที่พวกเขามีชั้นเรียนตอนเย็น เพราะแน่นอนฉันสนุกกับการเรียนในช่วงเย็นมากกว่าในตอนเช้า นอกจากนี้เจ้าหน้าที่และทุกคนที่นี่ช่วยเหลือกันเสมอ"},{id:14,image:"1628124330-yukari.jpg",campus_name:b,nationality_name:e,title:"คำแนะนำที่ดีที่สุดของฉัน มั่นใจในตัวเอง!",text:"Yukari Sato มาจากประเทศญี่ปุ่น เธอได้อาศัยและเรียนที่ MLI Hollywood ใน Los Angeles ในปีที่ผ่านมา เธอชอบระบายสี อ่านหนังสือ ทำอาหารและเต้น ในอนาคตเธออยากเป็นนักสอนเต้นและการแสดงมืออาชีพ\n\n                    ฉันอาศัยอยู่ที่บ้านพักใน North Hollywood ฉันเลือกบ้านเพราะฉันชอบงานแม่บ้านมาก เพื่อนของฉันจากโรงเรียน ชื่อNanami อาศัยอยู่ที่บ้านพักแนะนำฉัน สิ่งที่ดีที่สุดของการอยู่ที่นั่นคือมีสระว่ายน้ำในร่มและห้องออกกำลังกายที่อยู่ฝั่งตรงข้าม ฉันได้พัฒนาทักษะภาษาอังกฤษของฉันเพราะเจ้าของบ้านของฉันไม่พูดภาษาญี่ปุ่น ฉันอยากจะแนะนำบ้านพักให้กับนักเรียนที่ต้องการฝึกภาษาอังกฤษกับเจ้าของภาษาอังกฤษ\n                    \n                    หลังจากเลิกเรียนฉันชอบวาดรูประบายสี อ่านหนังสือ ทำอาหารและเต้น ฉันเต้น Jazz funk, hip hop, contemporary และ heels มีสตูดิโอสอนเต้นที่ยอดเยี่ยมมากมายในลอสแอนเจลิส ฉันคิดว่าสนามเด็กเล่น LA บนถนนเมลโรส (ใกล้กับหอพักเมลโรส) เป็นที่ที่ดีมากเพราะทุกคนมีความสุขกับการเต้น ฉันไปแค่ที่ Millenium เท่านั้นเพื่อฝึกอบรมและสอนเต้นพิเศษ Movement lifestyle ก็เป็นสตูดิโอสอนเต้นที่ดีใกล้สถานีรถไฟนอร์ทฮอลลีวูด ฉันชอบที่นั่นเพราะทุกคนมุ่งเน้นไปที่การเต้น ในอนาคตฉันอยากสอนเต้นและอยากจะแสดง ถ้าคุณสนใจการเต้นใน LA ฉันขอแนะนำให้คุณไปที่ Instagram หาครูที่คุณชอบและหาที่ที่พวกเขาสอน คุณไม่จำเป็นต้องรอจนกว่าคุณจะได้ไป LA เพื่อหาโรงเรียนสอนเต้นที่เหมาะสำหรับคุณ\n                    \n                    คำแนะนำที่ดีที่สุดของฉัน มั่นใจในตัวเอง!"},{id:13,image:"1628070618-miki2.jpg",campus_name:a,nationality_name:e,title:"ชั้นเรียนที่ดีที่สุดที่ฉันเคยมี",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นของสัปดาห์นี้คือ มิกิ จากประเทศญี่ปุ่น ในญี่ปุ่นเธอทำงานที่บริษัทรับจัดงานแต่ง แต่ตอนนี้เธอกำลังวางแผนอยากเป็นพนักงานต้อนรับบนเครื่องบินในอนาคต ในเวลาว่างเธอชอบไปนั่งเล่นในร้านกาแฟและทบทวนบทเรียน บางครั้งเธอก็ชอบไปพิพิธภัณฑ์ด้วย โดยเฉพาะพิพิธภัณฑ์ Hammer ฟรีและอยู่ใกล้กับโรงเรียน เธออาศัยอยู่ใน Westwood และอยากแนะนำให้กับนักเรียนใหม่\n                    \n                    \"ชั้นเรียน TOEFL ของฉันเป็นชั้นเรียนที่ดีที่สุดที่ฉันเคยเจอ เมื่อฉันเข้าเรียนฉันสามารถพัฒนาทักษะภาษาอังกฤษของฉันทั้งหมด เช่น การฟัง การเขียน การพูดและการอ่าน Kyle เป็นครูที่สอนสนุกมากๆ เรื่องเล่าของเขามักจะน่าสนใจและตลก นักเรียนทุกคนในชั้นเรียนจริงจังและมีแรงบันดาลใจ แม้ว่าจะมีนักเรียนญี่ปุ่นคนอื่นๆในห้องเรียน แต่พวกเขาก็พูดแต่ภาษาอังกฤษ ซึ่งเป็นประโยชน์มาก ตารางเรียน TOEFL ถูกจัดเพื่อให้เราฝึกฝนทักษะ 2 อย่างต่อวัน เช่น การอ่านและการพูดวันนึงและการเขียนและฟังในวันรุ่งขึ้น เรามีการสอบ TOEFL เดือนละครั้ง คะแนนของฉันดีขึ้นอย่างแน่นอน คะแนนแรกของฉันต่ำกว่าครั้งสุดท้ายมากและฉันคาดว่าคะแนนถัดไปของฉันจะสูงกว่าครั้งสุดท้าย ภาษาอังกฤษของฉันดีขึ้นมากเหมือนกัน ฉันอยากแนะนำให้โรงเรียนและชั้นเรียน TOEFL ให้กับทุกคน เมื่อครั้งแรกที่ฉันมา MLI ฉันรู้สึกกังวลมากเพราะฉันไม่สามารถพูดภาษาอังกฤษได้เลย แต่โรงเรียนก็ช่วยฉันได้มาก พวกเขาช่วยฉันหาธนาคารของอเมริกัน ฝึกงานและห้องเช่าเพื่อให้รู้สึกสบายขึ้น ตอนนี้ฉันรู้สึกสะดวกสบายมากขึ้นและฉันชอบ LA เพราะคนที่นี่เป็นคนใจดีและเป็นกันเอง \""},{id:12,image:"1628070274-mertcan-1.jpg",campus_name:a,nationality_name:e,title:"ทำไมต้องเลือก MLI",text:"ดาวเด่นสาขา Westwood\n\n                    นักเรียนที่โดดเด่นในสัปดาห์นี้คือ Mertcan เขามาจากตุรกี ปัจจุบันเขากำลังศึกษา ESL ขั้นสูง เวลาว่าง เขาชอบเล่นบาสเกตบอลในเมืองเวนิส เขาเล่นกับทุกคนที่นั่นที่เขาเพิ่งได้พบ เขายังทำงานคอมพิวเตอร์ในช่วงเวลาว่างของเขาเพื่อเรียนรู้เพิ่มเติม ปัจจุบันเขาอาศัยอยู่ใน Mar Vista และขอแนะนำที่นี่ให้กับนักเรียนเพราะใกล้กับ Venice Beach\n                    \n                    \"100% ที่ฉันอยากแนะนำ MLI ให้กับนักเรียนคนอื่นๆ ที่กำลังมองหาโรงเรียน ESL เพื่อศึกษาต่อที่ Los Angeles MLI เป็นโรงเรียนภาษาอังกฤษที่ถูกที่สุดเมื่อเทียบกับโรงเรียน ESL แห่งอื่นๆในพื้นที่และคุณภาพดีมาก โดยเฉพาะอย่างยิ่งสำหรับราคา นั่นคือสิ่งที่ทำให้ MLI ดีกว่าโรงเรียน ESL อื่นๆ โดยเฉพาะอย่างยิ่งฉันคิดว่าครูที่นี่ดีมาก ครูของฉัน Sheena และ Barry มีทัศนคติที่ดีและใจดี ฉันชอบ Westwood ด้วย คุณสามารถหาทุกสิ่งที่คุณต้องการได้ทั่วโรงเรียนเช่น LA Fitness และ UCLA MLI มีนักเรียนต่างชาติมากมาย ซึ่งทำให้การเรียนรู้เป็นเรื่องน่าสนใจเพราะคุณสามารถเรียนรู้เกี่ยวกับวัฒนธรรมที่แตกต่างกันได้ เมื่อถึงเวลาเรียน แค่ตั้งใจฟังครูและมุ่งเน้นเป้าหมายของคุณเองโดยไม่ต้องให้ใครรบกวน Los Angeles เป็นสถานที่ที่ดีในการอยู่อาศัย ฉันมาที่นี่เกือบ 2 ปีแล้วและชอบไปชายหาดมากที่สุด ฉันอยู่ใกล้เมืองเวนิส ซึ่งเป็นสถานที่ท่องเที่ยวที่น่าสนใจ ฉันยังคิดว่าหอดูดาว Griffith เป็นสถานที่ที่น่าสนใจเช่นกัน ฉันคิดว่าคนในลอสแอนเจลิสใจดีและชอบช่วยเหลือ ฉันรักวัฒนธรรมในลอสแอนเจลิสและขอแนะนำให้นักเรียนต่างชาติมาศึกษาที่นี่ “"},{id:11,image:"1628069853-tanice.jpg",campus_name:b,nationality_name:f,title:"Tanice - Brazil",text:"ดาวเด่นสาขา Hollywood\n\n                    Tanice มาจากปอร์ตูอาเลเกร ประเทศบราซิล เธอมาลอสแอนเจลิสเมื่อปีที่แล้วในวันหยุด ครั้งหนึ่งในอเมริกาเธอรู้ว่าภาษาอังกฤษของเธอไม่ค่อยดีนัก เธอลำบากในการพูดภาษาอังกฤษ แม้แต่การสั่งกาแฟก็ยากมาก เธอตัดสินใจที่จะพัฒนาทักษะภาษาอังกฤษและการเรียนที่ MLI Hollywood เวลาว่างเธอชอบไปทะเล ออกกำลังกาย ปัจจุบันเธอกำลังเรียนหลักสูตร ESL ขั้นสูง\n\n                    \"เมื่อฉันมาอเมริกา ฉันกลัวเพราะฉันไม่ได้พูดภาษาอังกฤษเลย แต่ฉันไม่ได้ปล่อยให้ความกลัวหยุดฉัน ฉันพยายามจะพูดเสมอ แม้ว่าจะทำผิดพลาดก็ตาม สิ่งที่ช่วยให้ฉันพัฒนาภาษาอังกฤษได้มากขึ้นคือการพูดคุยกับทุกคน คนขับรถ, คนทำกาแฟ และคนบนท้องถนน ฉันไม่อาย ดังนั้นฉันจึงเริ่มพูดคุยกับทุกคนที่สามารถหายใจได้! อีกสิ่งหนึ่งที่ช่วยให้ภาษาอังกฤษของฉันดีขึ้นคือ สนิทกับทุกคนไม่ใช่แค่ชาวบราซิลเท่านั้น แต่ยังมีผู้คนจากประเทศอื่นๆด้วย รู้สึกสบายใจที่ได้อยู่กับผู้คนจากประเทศของคุณเอง แต่คุณจะไม่พัฒนาภาษาอังกฤษของคุณเลย\n\n                    ฉันเรียนภาษาอังกฤษด้วยตัวเองโดยใช้วิดีโอ Youtube และมันช่วยได้มาก! ที่ฉันชอบมากที่สุดคือ \"ภาษาอังกฤษกับ Leila และ Sabrah\" และ \"Papa English\" บน YouTube พวกเขามักมีวิดีโอใหม่มากเสมอ มันสนุกและรวดเร็ว ?\n\n                    ฉันติดตามครูชาวบราซิลและชาวอเมริกันบน Instagram ด้วย ทุกๆวันครูจะให้คำแนะนำในการพูดเหมือนเจ้าของภาษา คุณควรตาม @mariovergara (คำแนะนำภาษาอังกฤษเป็นภาษาโปรตุเกสและภาษาอังกฤษ) บน Instagram อีกสิ่งที่ดีที่ฉันทำคือการใช้แอพสำนวนทุกวันก่อนนอน และเมื่อฉันอยู่ที่โรงยิม ฉันชอบที่จะใช้ Duolingo ช่วยให้สามารถใช้ภาษาอังกฤษในชีวิตประจำวัน ฉันไม่เคยเรียนไวยากรณ์ก่อนที่จะมาที่ MLI โรงเรียนช่วยฉันเรื่องการเขียนและการพูดได้อย่างถูกต้องโดยไม่ต้องมีคนแปล\""}]}],fetch:{},mutations:void 0}}("Westwood Campus","Hollywood Campus","Japanese","Other Nationalities","Chinese","Brazilian","Korean","Russian","th","","Arabic","Spanish","Turkish","France","Italian","All Campus")));